// Roem per verdiend daad-relikwie. Zo voeden daden de rangprogressie.
const PRESTATIE_ROEM = 3;

// opties komt rechtstreeks van pasScoreAanMetCheck: `naspel` bundelt de meldingen, en
// `alliantieBonus: false` betekent "dit is zelf al een afgeleide toekenning" — dan mag de
// solidariteitsbonus hieronder niet opnieuw vuren, want dan kaatst hij tussen twee bondgenoten
// heen en weer.
async function controleerAchievements(client, userId, oudeScore, nieuweScore, opties = {}) {
  const naspel = opties.naspel;
  const all = loadAchievements();
  const eigen = new Set(all[userId] || []);
  const members = loadMembers();
  const bijnaam = members[userId]?.bijnaam || 'Onbekende volgeling';

  let aangepast = false;
  // Score-relikwieën meten wat u deze week bovenop het zakgeld verdiende. Op de kale stand lagen
  // de eerste twee (1 en 5 punten) anders al klaar voordat u iets deed — en gingen ze stil over,
  // want de oude stand lag dan al boven de drempel en er volgde geen aankondiging.
  const oudVerdiend = verdiendeStand(oudeScore);
  const nieuwVerdiend = verdiendeStand(nieuweScore);

  for (const a of ACHIEVEMENTS) {
    if (eigen.has(a.id)) continue;

    if (nieuwVerdiend >= a.drempel) {
      eigen.add(a.id);
      aangepast = true;

      // Alleen aankondigen als de drempel NU is gepasseerd (oude score lag eronder)
      if (oudVerdiend < a.drempel) {
        try {
          if (!naspelRegel(naspel, `🏆 *Relikwie* — ${bijnaam}: *${a.naam}* (_${a.tekst}_)`, userId)) {
            await postToChannel(client, process.env.SLACK_CHANNEL_ID,
              `🏆 *RELIKWIE ONTGRENDELD* 🏆\n\n` +
              `> ${bijnaam} heeft *${a.naam}* verworven.\n` +
              `> _${a.tekst}_\n\n` +
              `— De Hoge Frituurraad`);
          }
        } catch (err) {
          console.error('Achievement post fout:', err.message);
        }
        logGebeurtenis('achievement', userId, `${bijnaam} verdiende het relikwie "${a.naam}"`);

        // Solidariteitsbonus: actieve alliantie-partner krijgt +1 als beloning voor trouw.
        // Niet als DEZE toekenning zelf al een afgeleide was (alliantieBonus: false) — anders
        // ketst de bonus heen en weer: A verdient een relikwie → B krijgt +1 → B passeert een
        // drempel → A krijgt +1 → A passeert een drempel → …
        try {
          // Eén willekeurige vrije bondgenoot, net als bij de Verbondszegen: een verbond van drie
          // levert geen dubbele solidariteit op.
          const partnerId = opties.alliantieBonus === false ? null
            : kiesEen(getBondgenoten(userId).filter(id => !isVerbannen(id)), Math.random());
          if (partnerId) {
            const partnerBijnaam = members[partnerId]?.bijnaam || 'de bondgenoot';
            const voorSolid = loadScores()[partnerId] || 0;
            await pasScoreAanMetCheck(client, partnerId, 1, { alliantieBonus: false, naspel });
            // Verbrand in een vloek? Dan geen aankondiging van punten die er niet zijn.
            if ((loadScores()[partnerId] || 0) <= voorSolid) throw new Error('bonus verbrand');
            if (!naspelRegel(naspel, `⚔️ *Solidariteitsbonus* — ${partnerBijnaam} +1 kroketpunt als bondgenoot van ${bijnaam}`, partnerId)) {
              await postToChannel(client, process.env.SLACK_CHANNEL_ID,
                `⚔️ *SOLIDARITEITSBONUS* ⚔️\n\n` +
                `> ${partnerBijnaam} ontvangt +1 kroketpunt als bondgenoot van ${bijnaam}, ` +
                `die zojuist *${a.naam}* verdiende.\n` +
                `> _Een verbond draagt zijn vruchten — ook voor de trouwe partner._\n\n` +
                `— De Hoge Frituurraad`);
            }
          }
        } catch (_) {}
      }
      // Anders: stilletjes markeren als ontgrendeld (backfill)
    }
  }

  if (aangepast) {
    all[userId] = [...eigen];
    saveAchievements(all);
  }
}

// ── Levenslange tellers ────────────────────────────────────────────────────────
// Per lid hoe vaak een daad is verricht. Voedt de daad-relikwieën (en is meteen de basis
// voor toekomstige statistieken). Wordt gevuld door telActie(), dezelfde funnel als de
// opdrachten — één hook in de spellogica, meerdere afnemers.
const loadTellers = () => readJSON('tellers.json', {});

// Venstertellers: { userId: { 'YYYY-MM-DD': { actie: aantal } } }. Wordt bij elke write
// gesnoeid tot het venster plus een week marge, zodat het bestand niet eindeloos groeit.
// Bewust gewone JSON: lib/state.js geeft alleen `.json` de mtime-cache en de atomaire write,
// en de backupdekking in lib/backup.js globt op `.json`.
function bumpVenster(userId, actie, aantal = 1) {
  try {
    const vandaag = dagSleutel();
    const alles = snoeiVenster(readJSON('venstertellers.json', {}), vandaag);
    const eigen = alles[userId] || {};
    const dag = eigen[vandaag] || {};
    dag[actie] = (dag[actie] || 0) + aantal;
    eigen[vandaag] = dag;
    alles[userId] = eigen;
    writeJSON('venstertellers.json', alles);
  } catch (err) {
    console.error('⚠️ Venstertellers bijwerken mislukt:', err.message);
  }
}

function bumpTeller(userId, actie, aantal = 1) {
  const data = loadTellers();
  const eigen = data[userId] || {};
  eigen[actie] = (eigen[actie] || 0) + aantal;
  data[userId] = eigen;
  writeJSON('tellers.json', data);
  return eigen[actie];
}

// Controleert de daad-relikwieën voor één actie. Verdiend relikwie → verkondiging + roem,
// zodat daden de rang laten stijgen. Gooit nooit: een relikwie mag geen spel breken.
async function controleerPrestaties(client, userId, actie, stand, naspel = null) {
  try {
    const kandidaten = ACHIEVEMENTS.filter(a => a.actie === actie && stand >= a.doel);
    if (!kandidaten.length) return;
    const all = loadAchievements();
    const eigen = new Set(all[userId] || []);
    const nieuw = kandidaten.filter(a => !eigen.has(a.id));
    if (!nieuw.length) return;
    const bijnaam = loadMembers()[userId]?.bijnaam || 'Onbekende volgeling';
    nieuw.forEach(a => eigen.add(a.id));
    all[userId] = [...eigen];
    saveAchievements(all);
    for (const a of nieuw) {
      logGebeurtenis('achievement', userId, `${bijnaam} verdiende het relikwie "${a.naam}" (${actie}: ${stand})`);
      if (!naspelRegel(naspel, `🏆 *Relikwie* — ${bijnaam}: *${a.naam}* (+${PRESTATIE_ROEM} roem)`, userId)) {
        await postToChannel(client, process.env.SLACK_CHANNEL_ID,
          `🏆 *RELIKWIE ONTGRENDELD* 🏆\n\n> ${bijnaam} heeft *${a.naam}* verworven.\n> _${a.tekst}_\n> ⚜️ *+${PRESTATIE_ROEM} roem* — daden wegen zwaarder dan punten.\n\n— De Hoge Frituurraad`);
      }
      await pasRoemAan(client, userId, PRESTATIE_ROEM);
    }
  } catch (err) {
    console.error('⚠️ Prestatie-controle mislukt:', err.message);
  }
}

// Kent één relikwie op id toe, los van tellers en drempels — voor eenmalige gebeurtenissen
// (de getuige van de vondst). Idempotent: wie het al heeft, krijgt niets en er wordt niets
// gepost. Zelfde uitbetaling als controleerPrestaties, zodat een relikwie altijd hetzelfde
// waard is, hoe het ook is verdiend.
async function kenRelikwieToe(client, userId, id) {
  try {
    const a = ACHIEVEMENTS.find(x => x.id === id);
    if (!a || !loadMembers()[userId]) return false;
    const all = loadAchievements();
    const eigen = new Set(all[userId] || []);
    if (eigen.has(id)) return false;
    eigen.add(id);
    all[userId] = [...eigen];
    saveAchievements(all);
    const bijnaam = loadMembers()[userId].bijnaam;
    logGebeurtenis('achievement', userId, `${bijnaam} verdiende het relikwie "${a.naam}"`);
    await postToChannel(client, process.env.SLACK_CHANNEL_ID,
      `🏆 *RELIKWIE ONTGRENDELD* 🏆\n\n> ${bijnaam} heeft *${a.naam}* verworven.\n> _${a.tekst}_\n> ⚜️ *+${PRESTATIE_ROEM} roem*.\n\n— De Hoge Frituurraad`);
    await pasRoemAan(client, userId, PRESTATIE_ROEM);
    return true;
  } catch (err) {
    console.error('⚠️ Relikwie toekennen mislukt:', err.message);
    return false;
  }
}

// Backfill bij startup: markeer alle reeds-verdiende achievements als ontgrendeld
// Zo voorkomen we dat oude leden bij hun volgende punt alsnog een lawine krijgen.
function backfillAchievements() {
  const scores = loadScores();
  const all = loadAchievements();
  let gewijzigd = false;

  for (const [userId, score] of Object.entries(scores)) {
    const eigen = new Set(all[userId] || []);
    for (const a of ACHIEVEMENTS) {
      if (verdiendeStand(score) >= a.drempel && !eigen.has(a.id)) {
        eigen.add(a.id);
        gewijzigd = true;
      }
    }
    if (eigen.size !== (all[userId]?.length || 0)) {
      all[userId] = [...eigen];
    }
  }
  if (gewijzigd) {
    saveAchievements(all);
    console.log('✓ Achievements ge-backfilled voor bestaande leden');
  }
}

// Backfill roem op basis van huidige scores (voor bestaande leden bij eerste deploy)
// Voegt de huidige score toe als startpunt — niet perfect maar eerlijk als beginwaarde.
function backfillRoem() {
  const scores = loadScores();
  const roemData = loadRoem();
  let gewijzigd = false;

  // Het zakgeld telt niet mee: dat is een cadeau, geen verdienste.
  for (const [userId, score] of Object.entries(scores)) {
    if (roemData[userId] === undefined && verdiendeStand(score) > 0) {
      roemData[userId] = verdiendeStand(score);
      gewijzigd = true;
    }
  }
  if (gewijzigd) {
    saveRoem(roemData);
    console.log('✓ Roem ge-backfilled voor bestaande leden');
  }
}

