// ── Willekeurige kroketevents ─────────────────────────────────────────────────

const KROKET_EVENTS = [
  { naam: 'Zonnestralen',     context: 'De zonnestralen hebben het vetbad bereikt — een kosmisch verschijnsel dat de puntentelling verstoort.' },
  { naam: 'Mosterdregen',     context: 'Het mosterd regent vandaag neer vanuit de kosmische smaakwolken boven de Hoge Frituurraad.' },
  { naam: 'Ragoutprofetie',   context: 'De ragout heeft gesproken. De Hoge Frituurraad interpreteert de tekens en past de standen aan.' },
  { naam: 'Vetbadtrillingen', context: 'Mysterieuze trillingen in het heilige vetbad hebben de kroketbalans verstoord.' },
  { naam: 'Korstcrisis',      context: 'Een plotselinge korstcrisis heeft de Hoge Frituurraad gedwongen corrigerende maatregelen te nemen.' },
  { naam: 'Maanstand',        context: 'De maanstand is ongunstig voor sommigen en gunstig voor anderen — de snackleer dicteert aanpassingen.' },
  { naam: 'Frituurolieprijs', context: 'De frituurolieprijs bereikte een historisch hoogtepunt. De Hoge Frituurraad trekt consequenties.' },
  { naam: 'Paneerlaagstoring',context: 'Een kosmische verstoring in de paneerlaag heeft de kroketbalans tijdelijk ontwricht.' },
];

// Berekent de decreten van dit event en LEGT ZE VAST. Vuurde eerder vijf in-memory
// setTimeouts over een venster van maximaal zeven uur, terwijl de minuut-cron de weekplanning
// al als `uitgevoerd` had weggeschreven. Een deploy of de nachtelijke herstart (03:00)
// tussen het eerste en het laatste decreet liet de rest dus verdampen: de ene helft van de
// leden had zijn punten, de andere niet, en de planning kwam niet terug. Precies de bug die
// de weekplanning hierboven al persistent maakte — één niveau dieper.
// De uitvoering doet de minuut-cron nu, uit kroketevent.json.
function planWillekeurigKroketEvent() {
  const now = new Date();
  const fmt = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Europe/Amsterdam', hour: 'numeric', minute: 'numeric', hour12: false,
  });
  const parts = fmt.formatToParts(now);
  const amsUur = parseInt(parts.find(p => p.type === 'hour').value);
  const amsMin = parseInt(parts.find(p => p.type === 'minute').value);
  const nuMinuten = amsUur * 60 + amsMin;

  const VROEGST = 10 * 60;
  const LATEST  = 17 * 60;
  const vanafMinuten = Math.max(nuMinuten + 5, VROEGST);
  if (vanafMinuten >= LATEST) {
    // Te laat op de dag voor een zinvol venster. Log dit: eerder verdween het event hier
    // stilzwijgend en was er die week geen enkel decreet, zonder spoor in de logs.
    console.log('⚡ Kroket-event overgeslagen: te laat op de dag voor een venster tot 17:00.');
    return;
  }

  const event = KROKET_EVENTS[Math.floor(Math.random() * KROKET_EVENTS.length)];
  const members = loadMembers();

  // Inhaalmechaniek: weeg de ±1 op basis van puntenachterstand zodat de stand niet te ver
  // uiteenloopt. Woog eerst op ROEM, en dat was fout: roem loopt nauwelijks uiteen (107–134)
  // terwijl de kroketpunten 1 tegen 59 stonden. Het mechanisme zag dus een balans die er niet
  // was. Nu op de weekscore, dezelfde grootheid die daadwerkelijk ontspoort.
  const puntData = loadScores();
  const punten = Object.keys(members).map(id => puntData[id] || 0);
  const gemPunten = punten.reduce((a, b) => a + b, 0) / Math.max(1, punten.length);
  const maxAfw = Math.max(1, ...punten.map(p => Math.abs(p - gemPunten)));

  const decreten = [];
  for (const [userId, lid] of Object.entries(members)) {
    const afwijking = (gemPunten - (puntData[userId] || 0)) / maxAfw; // achter → positief, voor → negatief
    const kansPlus = Math.min(0.82, Math.max(0.18, 0.5 + 0.32 * afwijking));
    let delta;
    if (Math.random() < kansPlus) {
      // Positieve beloning: wie achterloopt krijgt vaker een grotere (+2 / +3).
      let bedrag = 1;
      if (afwijking > 0) {
        const roll = Math.random();
        if (roll < afwijking * 0.40) bedrag = 3;
        else if (roll < afwijking * 0.80) bedrag = 2;
      }
      delta = bedrag;
    } else {
      delta = -1; // straf blijft mild
    }
    const doelMinuten = vanafMinuten + Math.floor(Math.random() * (LATEST - vanafMinuten));
    const delayMs = (doelMinuten - nuMinuten) * 60_000
      - (now.getSeconds() * 1000 + now.getMilliseconds());

    const dUur = Math.floor(doelMinuten / 60);
    const dMin = String(doelMinuten % 60).padStart(2, '0');
    console.log(`⚡ ${event.naam} — ${lid.bijnaam}: ~${dUur}:${dMin} AMS (${delta > 0 ? '+' : ''}${delta} pt)`);
    decreten.push({ userId, delta, doelTs: Date.now() + delayMs, gedaan: false });
  }

  // Bewaren náást de bestaande velden, zodat de `uitgevoerd`-vlag van de weekplanning die de
  // aanroeper net zette niet wordt overschreven.
  const bestaand = readJSON('kroketevent.json', {});
  writeJSON('kroketevent.json', { ...bestaand, event: { naam: event.naam, context: event.context }, decreten });
  console.log(`⚡ Kroket-event "${event.naam}" vastgelegd voor ${decreten.length} leden.`);
}

// Voert de decreten uit die aan de beurt zijn. Markeert een decreet als `gedaan` VÓÓR de
// puntenboeking: viel de LLM-keten daarna om, dan is het decreet niet nóg een keer betaald.
// Meer dan twee uur te laat (langdurige downtime) → stil laten vervallen; een decreet over een
// "kosmisch verschijnsel van dit moment" heeft de volgende ochtend geen betekenis meer.
const KROKET_EVENT_VERVAL_MS = 2 * 3_600_000;

async function voerKroketEventDecretenUit(client) {
  const ke = readJSON('kroketevent.json', {});
  if (!Array.isArray(ke.decreten) || !ke.decreten.length) return;
  const nu = Date.now();
  const index = ke.decreten.findIndex(d => !d.gedaan && nu >= d.doelTs);
  if (index === -1) return;

  const decreet = ke.decreten[index];
  const teLaat = nu > decreet.doelTs + KROKET_EVENT_VERVAL_MS;
  // Eerst vastleggen, dan uitvoeren.
  ke.decreten[index] = { ...decreet, gedaan: true };
  writeJSON('kroketevent.json', ke);
  if (teLaat) {
    console.log(`⚡ Kroket-eventdecreet voor ${decreet.userId} vervallen (te laat).`);
    return;
  }

  const lid = loadMembers()[decreet.userId];
  if (!lid) return; // lid is sinds de planning vertrokken
  const { delta } = decreet;
  try {
    const uitgesteldeZegens = []; // verbondszegen pas posten ná het decreet
    await pasScoreAanMetCheck(client, decreet.userId, delta, { uitgesteldeZegens }); // +1 telt ook als roempunt
    const richting = delta > 0
      ? `Dit werkt in het voordeel van ${lid.bijnaam}: +${delta} kroketpunt${delta > 1 ? 'en' : ''}.`
      : `Dit treft ${lid.bijnaam} ongunstig: −1 kroketpunt.`;
    const context = ke.event?.context || 'Een kosmisch verschijnsel verstoort de puntentelling.';
    const tekst = await kroketResponseMetVangnet(
      `${context} ${richting} Spreek dit kort en plechtig uit als decreet van de Kroket God. Noem de naam en het puntenaantal. Geen inleidingszin.`,
      280, false,
      `⚡ *${(ke.event?.naam || 'EEN KOSMISCH VERSCHIJNSEL').toUpperCase()}* ⚡\n\n> ${context}\n> ${richting}\n\n— De Almachtige Kroket God`
    );
    await postToChannel(client, process.env.SLACK_CHANNEL_ID, tekst);
    for (const post of uitgesteldeZegens) await post();
  } catch (err) {
    console.error(`Fout bij kroket-event (${lid.bijnaam}):`, err);
  }
}

// Maandag 09:30 — plan event op willekeurig moment ergens deze week (ma–vr 10:00–17:00).
// PERSISTENT in kroketevent.json (zoals de Gouden Kroket): een in-memory setTimeout van
// max. 4,5 dag overleefde de nachtelijke herstart (03:00) niet, waardoor het event in
// ~80% van de weken nooit vuurde. De minuut-cron voert de planning uit zodra het moment daar is.
// Eigen minuut (09:31), NIET 09:30: daar hangt de opkomst van de weekvijand aan, en CRON_LABELS is
// per EXPRESSIE gesleuteld. Met twee taken op één expressie kregen beide de skip-wrapper van het
// label 'Weekvijand (opkomst)', zodat een dashboard-"overslaan" van de weekvijand net zo goed deze
// weekplanning kon uitschakelen — wie van de twee het eerst vuurde, verbruikte de vlag.
planCron('31 9 * * 1', () => {
  const extraDagen = Math.floor(Math.random() * 5);         // 0=ma … 4=vr
  const doelUur   = 10 + Math.floor(Math.random() * 7);    // 10–16
  const doelMin   = Math.floor(Math.random() * 60);
  const delayMs   = extraDagen * 24 * 60 * 60_000
                  + (doelUur - 9) * 60 * 60_000
                  + (doelMin - 30) * 60_000;
  const dagNamen  = ['maandag', 'dinsdag', 'woensdag', 'donderdag', 'vrijdag'];
  writeJSON('kroketevent.json', { doelTs: Date.now() + delayMs, uitgevoerd: false });
  console.log(`⚡ Kroket-event gepland op ${dagNamen[extraDagen]} ~${doelUur}:${String(doelMin).padStart(2, '0')} AMS (persistent)`);
}, { timezone: 'Europe/Amsterdam' });

// ── De Gouden Kroket: wekelijkse schatzoektocht ───────────────────────────────
// Op een willekeurig moment (ma–vr, 10:00–16:30) verschijnt de Gouden Kroket in het kanaal.
// De EERSTE volgeling die het bericht met :lekker_kroketje: zegent, grijpt hem (+3).
// De geplande tijd staat persistent in goudenkroket.json zodat de nachtelijke herstart
// (03:00) hem niet wist; een minuut-cron post zodra het moment daar is.

const loadGoudenKroket = () => readJSON('goudenkroket.json', {});
const saveGoudenKroket = (data) => writeJSON('goudenkroket.json', data);

async function postGoudenKroket(client, channelId = process.env.SLACK_CHANNEL_ID) {
  const tekst =
    `⚡ *DE GOUDEN KROKET IS VERSCHENEN* ⚡\n\n` +
    `> Uit het kokende vet rijst de legendarische *Gouden Kroket* — glanzend, volmaakt gepaneerd, eenmalig.\n` +
    `> De EERSTE volgeling die dit bericht zegent met :lekker_kroketje: grijpt hem en ontvangt *+3 kroketpunten*.\n\n` +
    `— De Hoge Frituurraad`;
  const msg = await client.chat.postMessage({ channel: channelId, text: tekst });
  // `geplaatstOp` is nodig voor het graaivenster: zonder dat bleef een ongepakte kroket eeuwig
  // liggen en las de minuut-cron er tot de volgende maandag elke minuut de reacties van.
  saveGoudenKroket({ ts: msg.ts, kanaal: channelId, geplaatst: true, gepakt: false, geplaatstOp: Date.now() });
  console.log('🥇 Gouden Kroket geplaatst');
}

// Kroon een volgeling tot grijper van de Gouden Kroket (+3). Geeft true terug als de
// kroning doorging (kroket nog niet gepakt, winnaar is lid en niet verbannen).
async function grijpGoudenKroket(client, userId) {
  const gk = loadGoudenKroket();
  if (!gk.geplaatst || gk.gepakt) return false;
  const gkMembers = loadMembers();
  if (!gkMembers[userId] || isVerbannen(userId)) return false;
  saveGoudenKroket({ ...gk, gepakt: true, winnaar: userId, gepaktOp: Date.now() });
  const winnaarNaam = gkMembers[userId].bijnaam;
  const uitgesteldeZegens = [];
  await pasScoreAanMetCheck(client, userId, 3, { channelId: gk.kanaal, uitgesteldeZegens });
  logGebeurtenis('goudenkroket', userId, `${winnaarNaam} greep de Gouden Kroket (+3)`);
  await telActie(client, userId, 'gouden_kroket');
  await postToChannel(client, gk.kanaal,
    `🥇 *DE GOUDEN KROKET IS GEGREPEN* 🥇\n\n` +
    `> *${winnaarNaam}* was de snelste van het genootschap en grijpt de Gouden Kroket uit het kokende vet — *+3 kroketpunten*.\n\n` +
    `— De Hoge Frituurraad`);
  for (const post of uitgesteldeZegens) await post();
  return true;
}

// Hoe lang de Gouden Kroket te grijpen valt. Zonder venster bleef een ongepakte kroket tot de
// volgende maandag "geplaatst" staan, en dan deed de minuut-cron elke minuut een reactions.get:
// ~9.000 Slack-calls voor een schat die niemand meer kwam halen. Narratief was het net zo raar —
// de kroket lag eeuwig te glanzen zonder dat iemand zei dat de kans voorbij was.
// Drie uur: lang genoeg om een lunchpauze te overleven, kort genoeg om een race te blijven.
const GOUDEN_KROKET_VENSTER_MS = 3 * 3_600_000;

// Vangnet: reaction_added-events komen niet binnen zolang de Slack-app die
// event-subscription mist. Zolang er een ongepakte Gouden Kroket ligt, leest de
// minuut-cron daarom zelf de reacties op het schatbericht. Slack geeft de reageerders
// terug in volgorde van reageren, dus de eerste geldige volgeling wint alsnog.
async function pollGoudenKroketReacties(client) {
  const gk = loadGoudenKroket();
  if (!gk.geplaatst || gk.gepakt || !gk.ts) return;
  const res = await client.reactions.get({ channel: gk.kanaal, timestamp: gk.ts, full: true });
  const reactie = (res.message?.reactions || []).find(r => r.name === 'lekker_kroketje');
  for (const uid of reactie?.users || []) {
    if (await grijpGoudenKroket(client, uid)) return;
  }
}

// Maandag 09:35 — plan de Gouden Kroket op een willekeurig moment deze week (persistent).
// Berekend als delay t.o.v. het cron-moment (09:35 AMS) zodat de servertijdzone niet uitmaakt.
planCron('35 9 * * 1', () => {
  const extraDagen = Math.floor(Math.random() * 5);        // 0=ma … 4=vr
  const doelUur = 10 + Math.floor(Math.random() * 7);      // 10–16
  const doelMin = Math.floor(Math.random() * 60);
  const delayMs = extraDagen * 24 * 60 * 60_000
                + (doelUur - 9) * 60 * 60_000
                + (doelMin - 35) * 60_000;
  saveGoudenKroket({ geplandVoor: Date.now() + delayMs, geplaatst: false, gepakt: false });
  const dagNamen = ['maandag', 'dinsdag', 'woensdag', 'donderdag', 'vrijdag'];
  console.log(`🥇 Gouden Kroket gepland op ${dagNamen[extraDagen]} ~${doelUur}:${String(doelMin).padStart(2, '0')} AMS`);
}, { timezone: 'Europe/Amsterdam' });

// Elke vijf minuten: is er een gast wiens drie werkdagen erop zitten? Dan neemt hij afscheid.
planCron('*/5 * * * *', () => laatGastVertrekken(app.client)
  .catch(err => console.error('Fout bij gastvertrek:', err.data?.error || err.message)),
{ timezone: 'Europe/Amsterdam' });

// Werkdagen, elke minuut van 08:00 tot 08:59: de ochtendgroet van de gasten (ochtendgroetTik).
planCron('* 8 * * 1-5', () => ochtendgroetTik(app.client)
  .catch(err => console.error('⚠️ Ochtendgroet mislukt:', err.data?.error || err.message)),
{ timezone: 'Europe/Amsterdam' });

// Het gastendebat (lib/gastendebat.js): woensdag 15:00 begint het, 17:00 telt de Kroket God. De stand
// staat in gastendebat.json, zodat een herstart ertussen niets uitmaakt. Wie tijdens het debat zou
// vertrekken, doet niet mee.
const DEBAT_DUUR_MS = 2 * 3_600_000;
async function startGastendebat(client) {
  if (instelling('stilModus') || instelling('alleenTestkanaal')) return;
  const dag = dagSleutel();
  const vorig = readJSON('gastendebat.json', {});
  if (vorig.dag === dag) return;
  const nu = Date.now();
  const paar = kiesDebaters(gastenVandaag().filter(g => !g.vertrekOp || g.vertrekOp > nu + DEBAT_DUUR_MS).map(g => g.id));
  if (!paar) { console.log('⚖️ Gastendebat: minder dan twee gasten, dus geen debat.'); return; }
  const personas = loadPersonas();
  const [a, b] = paar.map(id => ({ id, ...personas[id] }));
  const nr = kiesStelling(vorig.gebruikt || []);
  const stelling = STELLINGEN[nr];
  const res = await postToChannel(client, KANAAL(),
    `⚖️ *GASTENDEBAT* ⚖️\n\n> _${stelling}_\n> 1️⃣ *${ontsnapMrkdwn(a.naam)}* verdedigt de stelling · 2️⃣ *${ontsnapMrkdwn(b.naam)}* valt haar aan\n\n` +
    `Stem met 1️⃣ of 2️⃣ onder dit bericht; het debat zelf staat in de thread. Om 17:00 telt de Kroket God, en de winnaar blijft een werkdag langer.\n\n— De Kroket God`);
  if (!res?.ts) return;
  writeJSON('gastendebat.json', { dag, kanaal: KANAAL(), ts: res.ts, a: a.id, b: b.id, stelling, gebruikt: [...(vorig.gebruikt || []), nr].slice(-15), gesloten: false });
  for (const emoji of [STEM_A, STEM_B]) {
    await slackLimiter.schedule(() => client.reactions.add({ channel: KANAAL(), timestamp: res.ts, name: emoji })).catch(() => {});
  }
  const kader = (tegen) => `Je debatteert in het kanaal van het genootschap tegen ${tegen.naam}, over de stelling "${stelling}".`;
  const gezegd = {};
  const beurt = async (spreker, opdracht) => {
    try { gezegd[spreker.id] = await personaResponse(spreker, `${opdracht} Helemaal in karakter, geen inleidingszin.`, 260); }
    catch (err) { console.warn(`⚠️ Debatbeurt van ${spreker.naam} mislukt:`, err.message); gezegd[spreker.id] = null; }
    await postAlsPersona(client, KANAAL(), spreker, gezegd[spreker.id] || `_${spreker.naam} schraapt zijn keel, maar er komt niets uit._`, { thread_ts: res.ts, onderling: true });
  };
  await beurt(a, `${kader(b)} Jij verdedigt de stelling. Geef je openingsbetoog in twee tot drie zinnen.`);
  await beurt(b, `${kader(a)} Jij bent tegen de stelling. Geef je openingsbetoog in twee tot drie zinnen.`);
  const weerwoord = (spreker, tegen) => beurt(spreker, `${kader(tegen)} ${wrapOnvertrouwd('Wat je tegenstander net zei', gezegd[tegen.id] || '(niets)')} Weerleg dat in één tot twee zinnen.`);
  await weerwoord(a, b);
  await weerwoord(b, a);
}

async function sluitGastendebat(client) {
  if (instelling('stilModus') || instelling('alleenTestkanaal')) return;
  const d = readJSON('gastendebat.json', {});
  if (d.dag !== dagSleutel() || d.gesloten) return;
  writeJSON('gastendebat.json', { ...d, gesloten: true });
  const res = await slackLimiter.schedule(() => client.reactions.get({ channel: d.kanaal, timestamp: d.ts, full: true }));
  const members = loadMembers();
  const stemmen = telDebatStemmen(res.message?.reactions || [], u => u !== BOT_USER_ID && !!members[u] && !isVerbannen(u));
  const winnaar = debatWinnaar(stemmen);
  const personas = loadPersonas();
  const naam = (id) => ontsnapMrkdwn(personas[id]?.naam || 'een vertrokken gast');
  let regel = stemmen.a + stemmen.b ? 'Gelijkspel: niemand wint iets, en de stelling blijft onbeslist.' : 'Niemand stemde. De stelling blijft onbeslist.';
  if (winnaar && personas[d[winnaar]]) {
    const id = d[winnaar];
    personas[id] = naDebatWinst(personas[id]);
    savePersonas(personas);
    logAudit('persona', `${personas[id].naam} (${id}) won het gastendebat (${stemmen.a}-${stemmen.b})`);
    regel = `*${naam(id)}* wint en blijft een werkdag langer.`;
  }
  await postToChannel(client, d.kanaal,
    `⚖️ *UITSLAG GASTENDEBAT* ⚖️\n\n> _${d.stelling}_\n> 1️⃣ ${naam(d.a)}: *${stemmen.a}* · 2️⃣ ${naam(d.b)}: *${stemmen.b}*\n> ${regel}\n\n— De Kroket God`);
}

planCron('0 15 * * 3', () => startGastendebat(app.client)
  .catch(err => console.error('⚠️ Gastendebat mislukt:', err.data?.error || err.message)),
{ timezone: 'Europe/Amsterdam' });
planCron('0 17 * * 3', () => sluitGastendebat(app.client)
  .catch(err => console.error('⚠️ Uitslag gastendebat mislukt:', err.data?.error || err.message)),
{ timezone: 'Europe/Amsterdam' });

// Werkdagen 09:00: na de ochtendgroet zet de Kroket God op een rij wie er vandaag is.
planCron('0 9 * * 1-5', async () => {
  try {
    if (instelling('stilModus') || instelling('alleenTestkanaal')) return;
    const gasten = gastenVandaag();
    if (gasten.length) await postToChannel(app.client, KANAAL(), `🚪 *DE GASTEN VAN VANDAAG* 🚪\n\n${gastenVandaagTekst(gasten)}\n\n— De Kroket God`);
  } catch (err) {
    console.error('⚠️ Gasten van vandaag mislukt:', err.data?.error || err.message);
  }
}, { timezone: 'Europe/Amsterdam' });

// Elke minuut: is het geplande moment daar? Post dan. Meer dan 6 uur te laat (bot lag eruit,
// of stille modus duurde lang) → plan vervalt stilletjes tot de volgende maandag.
planCron('* * * * *', async () => {
  // Kroket-event: persistente planning uitvoeren zodra het moment daar is. Staat vóór het
  // Gouden Kroket-blok (dat een early return heeft). Meer dan 8 uur te laat (langdurige
  // downtime) → planning stilletjes laten vervallen, geen mosterd na de maaltijd.
  try {
    const ke = readJSON('kroketevent.json', {});
    if (ke.doelTs && !ke.uitgevoerd && Date.now() >= ke.doelTs) {
      writeJSON('kroketevent.json', { ...ke, uitgevoerd: true });
      if (Date.now() < ke.doelTs + 8 * 3_600_000) planWillekeurigKroketEvent();
    }
    // Eén decreet per minuut is ruim genoeg: ze staan minuten uit elkaar, en zo blijft de
    // minuut-cron kort.
    await voerKroketEventDecretenUit(app.client);
  } catch (err) {
    console.error('⚠️ Kroket-event check mislukt:', err.message);
  }
  try {
    const gk = loadGoudenKroket();
    if (gk.geplaatst && !gk.gepakt) {
      // Oudere records hebben geen `geplaatstOp`; die krijgen hem nu, zodat een kroket die op
      // dit moment nog écht open ligt niet ten onrechte vervalt.
      if (!gk.geplaatstOp) { saveGoudenKroket({ ...gk, geplaatstOp: Date.now() }); return; }
      if (Date.now() > gk.geplaatstOp + GOUDEN_KROKET_VENSTER_MS) {
        saveGoudenKroket({});
        await postToChannel(app.client, gk.kanaal,
          `🥇 *DE GOUDEN KROKET IS VERZONKEN* 🥇\n\n` +
          `> Niemand greep hem. De Gouden Kroket is terug in het kokende vet gezakt en lost daar op.\n` +
          `> Wat glanst wacht niet. Volgende week rijst er misschien een nieuwe.\n\n— De Hoge Frituurraad`);
        return;
      }
      await pollGoudenKroketReacties(app.client);
      return;
    }
    if (!gk.geplandVoor || gk.geplaatst) return;
    const nu = Date.now();
    if (nu < gk.geplandVoor) return;
    if (nu > gk.geplandVoor + 6 * 3_600_000) { saveGoudenKroket({}); return; }
    if (instelling('stilModus') || instelling('alleenTestkanaal')) return; // volgende minuut opnieuw
    await postGoudenKroket(app.client);
  } catch (err) {
    console.error('⚠️ Gouden Kroket post mislukt:', err.message);
  }
}, { timezone: 'Europe/Amsterdam' });

