// ── Cron: dagelijks 08:30 — verjaardagscheck ──────────────────────────────────

planCron('30 8 * * *', async () => {
  try {
    // Verjaardagen zijn een uitzondering op de weekendrust — ze worden altijd verstuurd.
    // Als het weekend is, vermeldt de bot dat het bericht pas maandag wordt gelezen.
    const isWeekend = isWeekendAms();

    const nu = new Date();
    const amsDatumParts = new Intl.DateTimeFormat('en-US', {
      timeZone: 'Europe/Amsterdam', day: '2-digit', month: '2-digit',
    }).formatToParts(nu);
    const dag   = amsDatumParts.find(p => p.type === 'day').value;
    const maand = amsDatumParts.find(p => p.type === 'month').value;
    const vandaag = `${dag}-${maand}`;

    const members = loadMembers();
    for (const [id, lid] of Object.entries(members)) {
      // Match zowel DD-MM als DD-MM-YYYY
      const lidDatum = lid.verjaardag?.split('-').slice(0, 2).join('-');
      if (lidDatum === vandaag) {
        const uitgesteldeZegens = []; // verbondszegen pas posten ná de verjaardagszegen
        await pasScoreAanMetCheck(app.client, id, 3, { uitgesteldeZegens }); // 3 punten bonus op verjaardag
        const weekendNoot = isWeekend
          ? ` Het is weekend en de Kroket God rust normaliter — maar een verjaardag duldt geen uitstel. Voeg aan het einde toe dat dit bericht pas maandag zal worden gelezen, maar dat de kroket God de geboortedag niet ongemarkeerd kon laten.`
          : '';
        const tekst = await kroketResponse(
          `Vandaag is het de verjaardag van ${lid.bijnaam}. Stuur een plechtige kroket-verjaardagszegen en kondig aan dat 3 kroketpunten worden toegekend als geschenk van de Kroket God. Geen inleidingszin.` +
          (lid.favorieteKroket ? ` Verwijzing naar hun favoriete kroket (${lid.favorieteKroket}) is welkom.` : '') +
          weekendNoot,
          450, false
        );
        // Verjaardag verdient een stem: tekst + audio
        await postMetStem(app.client, process.env.SLACK_CHANNEL_ID, tekst);
        for (const post of uitgesteldeZegens) await post();
      }
    }
  } catch (error) {
    console.error('Fout bij verjaardagscheck:', error);
  }
}, { timezone: 'Europe/Amsterdam' });

// ── Waakhond: elke minuut controleren of Slack bereikbaar is ───────────────────
// auth.test is de lichtste call die er is (Tier 4, ruim binnen de limieten) en raakt geen
// LLM-quota. Bij aanhoudende onbereikbaarheid stopt het proces; Docker start het opnieuw met een
// frisse Socket Mode-verbinding. Dat is nodig omdat een kapotte verbinding zich niet altijd
// zelf herstelt: bij de DNS-storing bleef de bot uren stil terwijl het proces gezond leek.
async function controleerSlackVerbinding() {
  if (!isReady) return; // nog aan het opstarten
  try {
    await app.client.auth.test();
    if (slackFouten > 0) {
      console.log(`✓ Slack weer bereikbaar na ${slackFouten} mislukte controle(s).`);
    }
    slackLaatstOk = Date.now();
    slackFouten = 0;
    slackLaatsteFout = null;
  } catch (err) {
    slackFouten++;
    slackLaatsteFout = err.data?.error || err.code || err.message || 'onbekend';
    const minuten = Math.round((Date.now() - slackLaatstOk) / 60_000);
    console.error(`⚠️ Slack onbereikbaar (${slackFouten}× achter elkaar, ${minuten} min): ${slackLaatsteFout}`);

    // Zelfherstel, maar hoogstens één keer per half uur: blijft de oorzaak bestaan (DNS plat,
    // internet eruit), dan heeft doorstarten geen zin en zou een herstartlus alleen het log
    // vervuilen en de spelstaat-writes onderbreken.
    if (slackFouten >= SLACK_MAX_FOUTEN && Date.now() - laatsteZelfherstart > ZELFHERSTART_PAUZE_MS) {
      laatsteZelfherstart = Date.now();
      console.error(`🔁 Slack ${SLACK_MAX_FOUTEN} minuten onbereikbaar — proces stopt zodat Docker opnieuw start.`);
      setTimeout(() => process.exit(1), 1000); // even ruimte om het log weg te schrijven
    }
  }
}

planCron('* * * * *', controleerSlackVerbinding, { timezone: 'Europe/Amsterdam' });

// ── Dagelijkse steun van de Frituurraad ────────────────────────────────────────
// Waar de redistributie WEL hoort: bij de puntenbronnen. Wie ver achterloopt op de koploper
// krijgt elke werkdag een kleine steun. Bewust hier en niet in het Vetbad: een kansbonus tegen
// de bank print punten bij (EV van −5% naar +23%), een begrensde bron doet dat niet.
// Gedempt: hoogstens STEUN_MAX per dag per lid, en alleen onder de drempel.
const STEUN_DREMPEL = 0.35;  // onder 35% van de koploper kom je in aanmerking
const STEUN_MAX = 2;         // hoogstens twee punten per dag

planCron('30 12 * * 1-5', async () => {
  try {
    const members = loadMembers();
    const scores = loadScores();
    const alle = Object.keys(members).map(id => scores[id] || 0);
    const leider = Math.max(...alle, 0);
    if (leider < 10) return; // nog geen echte kloof; niets te nivelleren
    const grens = leider * STEUN_DREMPEL;
    const geholpen = [];
    for (const [id, lid] of Object.entries(members)) {
      if (isVerbannen(id)) continue;
      const eigen = scores[id] || 0;
      if (eigen >= grens) continue;
      // Hoe verder achter, hoe meer steun — maar nooit meer dan STEUN_MAX.
      const bedrag = Math.max(1, Math.min(STEUN_MAX, Math.ceil((grens - eigen) / grens * STEUN_MAX)));
      await pasScoreAanMetCheck(app.client, id, bedrag, { channelId: process.env.SLACK_CHANNEL_ID });
      // Neutraal logtype en neutrale omschrijving: 'bedelarij' met "stand X, koploper Y" verried
      // in het weekoverzicht precies wie er bijgestuurd werd.
      logGebeurtenis('score', id, `${lid.bijnaam} ontving de dagelijkse gave (+${bedrag})`);
      geholpen.push(`*${lid.bijnaam}* +${bedrag}`);
    }
    if (!geholpen.length) return;
    // De gebeurtenis blijft zichtbaar — anders stijgen saldi zonder verklaring — maar de REDEN
    // niet. Een grillig gulle Kroket God past in het karakter; "wie achterloopt krijgt steun"
    // zou verklappen wie er geholpen wordt.
    await postToChannel(app.client, process.env.SLACK_CHANNEL_ID,
      `🥔 *DE DAGELIJKSE GAVE* 🥔\n\n> De Kroket God strooit met gunsten zoals het vet met spatten: onberekenbaar, maar nooit zonder reden.\n> Vandaag deelt hij uit aan ${geholpen.join(' · ')}.\n> _De frituur beweegt in raadselen._\n\n— De Hoge Frituurraad`);
  } catch (err) {
    console.error('Fout bij dagelijkse steun:', err);
  }
}, { timezone: 'Europe/Amsterdam' });

// ── Rang-voorrecht: wekelijkse gunst (Grote Paneermeester en hoger) ────────────
// Maandagochtend krijgt elke drager van dit voorrecht een gratis power-up uit de
// Aflatenhandel. Templated (geen LLM-call) — het is een vaste, formulematige gunst.
const GUNST_POOL = ['zegen', 'dubbele_eer', 'gouden_korst'];

planCron('0 10 * * 1', async () => {
  try {
    const members = loadMembers();
    const begunstigd = [];
    for (const id of Object.keys(members)) {
      if (!getVoorrechten(id).gunstAanwijzen || isVerbannen(id)) continue;
      // Kies een gunst die nog niet op dit lid actief is; alles actief → overslaan.
      const kandidaten = GUNST_POOL.filter(k => !heeftPowerup(id, k));
      if (!kandidaten.length) continue;
      const gunst = kandidaten[Math.floor(Math.random() * kandidaten.length)];
      geefPowerup(id, gunst);
      registreerWinkelAankoop(id, gunst, 0, null, 'rangvoorrecht');
      logGebeurtenis('winkel', id, `${members[id].bijnaam} ontving ${WINKEL_ITEMS[gunst].naam} als wekelijkse rang-gunst`);
      begunstigd.push(`*${members[id].bijnaam}* — ${WINKEL_ITEMS[gunst].icoon} ${WINKEL_ITEMS[gunst].naam}`);
    }
    if (!begunstigd.length) return;
    await postToChannel(app.client, process.env.SLACK_CHANNEL_ID,
      `⚜️ *DE WEKELIJKSE GUNST* ⚜️\n\n> De Hoge Frituurraad beloont wie de rang van Grote Paneermeester heeft bereikt:\n> ${begunstigd.join('\n> ')}\n\n— De Hoge Frituurraad`);
  } catch (err) {
    console.error('Fout bij wekelijkse rang-gunst:', err);
  }
}, { timezone: 'Europe/Amsterdam' });

registreerFeature({
  naam: 'rang-voorrechten',
  help: [{ gebruik: '/kroketgod decreet [tekst]', verwacht: 'alleen de Opperkroket: vaardig het Decreet van de Dag uit (`decreet wis` trekt het in)' }],
});

registreerFeature({
  naam: 'profeet-van-de-week',
  state: ['profeet.json'],
  help: [{ gebruik: '/kroketgod zegen [naam]', verwacht: 'alleen de Profeet van de Week (weekkampioen): deel één heilige zegen uit (+1)' }],
});

// ── Cron: zondag 23:59 — weekkampioen & wekelijkse kroketpunten-reset ──────────
// Kroketpunten resetten elke week (zondagnacht); roempunten blijven permanent staan. Het zakgeld
// volgt maandag 08:00 met een eigen cron (hieronder).

planCron('59 23 * * 0', async () => {
  try {
    await voerWeekkampioenUit(app.client);
  } catch (error) {
    console.error('Fout bij weekkampioen:', error);
  }
}, { timezone: 'Europe/Amsterdam' });

// ── Cron: maandag 08:00 — zakgeld ──────────────────────────────────────────────
// Bewust zónder CRON_LABELS-entry: een dashboard-"overslaan" zou hier niets overslaan, want de
// inhaalslag van 09:00 deelt een gemiste ronde alsnog uit. Een knop die niet doet wat hij zegt
// is erger dan geen knop.
planCron('0 8 * * 1', async () => {
  try {
    await deelZakgeldUit(app.client);
  } catch (error) {
    console.error('Fout bij zakgeld:', error);
  }
}, { timezone: 'Europe/Amsterdam' });

async function voerWeekkampioenUit(client) {
  const scores = loadScores();
  const gesorteerd = Object.entries(scores).sort((a, b) => b[1] - a[1]);
  // De Frituurbeurs rekent hier af en niet in een eigen cron: het moet vóór de puntenreset
  // hieronder gebeuren (daarna is de eindstand weg), en zo erft de beurs de inhaalslag die deze
  // functie bij opstarten al heeft. Alleen leden tellen mee voor de eindstand — een oud-lid in
  // scores.json is geen plek in de ranglijst. Ballingen doen niet mee (zie handelbaarPlek).
  //
  // Dezelfde ordening als het koersenbord (stand aflopend, dan op bijnaam), zodat de plek die een
  // handelaar de hele week in zijn portefeuille zag, ook de plek is waarop hij wordt afgerekend.
  // Zonder die gelijke tie-break kon een gelijke stand bovenaan hier anders vallen dan daar.
  const beursLeden = loadMembers();
  const beursEindstand = gesorteerd
    .filter(([id]) => beursLeden[id] && !isVerbannen(id))
    .sort((a, b) => b[1] - a[1] || beursLeden[a[0]].bijnaam.localeCompare(beursLeden[b[0]].bijnaam));

  // Alleen een kampioen kronen als er deze week überhaupt punten zijn verdiend — dus als iemand
  // boven het zakgeld uitkwam. Anders kroonde een week zonder spel wie niets uitgaf.
  const heeftPunten = gesorteerd.length > 0 && kampioenWaardig(gesorteerd[0][1]);
  if (heeftPunten) {
    const members = loadMembers();
    const [kampioenId, kampioenScore] = gesorteerd[0];
    const kampioenBijnaam = members[kampioenId]?.bijnaam || kampioenId;
    // De kampioen wordt komende week PROFEET VAN DE FRITUUR: extra eerbied van de Kroket God
    // en één heilige zegen te vergeven via `/kroketgod zegen [naam]`.
    writeJSON('profeet.json', {
      userId: kampioenId,
      weekStart: getMondayOfWeek(new Date(Date.now() + 26 * 3_600_000)), // de nieuwe week (ma)
      zegenGebruikt: false,
    });
    // De Gunst beloont pas hier, en op NETTO: wie deze week meer weggaf dan hij kreeg, krijgt
    // roem. Vóór de reset, want de punten gaan zo op nul — maar de roem blijft eeuwig, en dat
    // is precies het verschil dat de Gunst de moeite waard maakt.
    await keerGulheidUit(client);

    const tekst = await kroketResponseMetVangnet(
      `Het is zondagnacht — het einde van de kroketweek. Kondig ${kampioenBijnaam} aan als WEEKKAMPIOEN met ${kampioenScore} kroketpunten. ` +
      `Dramatisch en plechtig, met kroning. Maak duidelijk dat de kroketpunten nu voor iedereen op nul gaan voor een frisse nieuwe week (maandagochtend volgt het zakgeld), ` +
      `maar dat de roempunten — de eeuwige prestige — voor altijd blijven staan. ` +
      `Verkondig ook dat ${kampioenBijnaam} de komende week DE PROFEET VAN DE FRITUUR is: één heilige zegen te vergeven via "/kroketgod zegen [naam]". Geen inleidingszin.`,
      500, false,
      `👑 *DE WEEKKAMPIOEN* 👑\n\n> *${kampioenBijnaam}* wint de kroketweek met *${kampioenScore} kroketpunten* en is komende week DE PROFEET VAN DE FRITUUR (één zegen te vergeven via \`/kroketgod zegen [naam]\`).\n> De kroketpunten gaan op nul (maandag 08:00 volgt het zakgeld); de roem blijft eeuwig.\n\n— De Almachtige Kroket God`
    );
    await postMetStem(client, process.env.SLACK_CHANNEL_ID, tekst);
  }

  // De beurs ná de kroning en vóór de reset: de kampioen is het nieuws, de beurs is het naspel.
  try {
    await rekenBeursAf(client, beursEindstand);
  } catch (err) {
    console.error('⚠️ Beursafrekening mislukt:', err.message);
  }

  // Reset ALLEEN de kroketpunten (scores) naar 0 — roem blijft permanent staan.
  const nieuwScores = {};
  Object.keys(scores).forEach(id => { nieuwScores[id] = 0; });
  saveScores(nieuwScores);
  // Marker voor de opstart-inhaalslag: welke week is als laatste gereset? (Bij de normale
  // zondag-23:59-run is dat de kómende week; bij een inhaalslag doordeweeks de huidige.)
  // Onvoorwaardelijk — óók zonder kampioen, anders blijft de inhaalslag dagelijks herhalen.
  const nieuweWeek = getMondayOfWeek(new Date(Date.now() + 26 * 3_600_000));
  writeJSON('weekreset.json', { week: nieuweWeek });
  // De zakgeldlijst van die week leeg: de reset heeft net ieders punten weggeveegd, dus ook het
  // zakgeld van een eventuele eerdere uitkering. De volgende uitdeelronde (maandag 08:00, of de
  // inhaalslag van 09:00) vult hem weer.
  writeJSON('zakgeld.json', { week: nieuweWeek, ontvangen: [] });
  logGebeurtenis('week_reset', null, heeftPunten ? 'Kroketpunten gereset; weekkampioen gekroond' : 'Kroketpunten gereset (geen punten deze week)');
  // Het wereldbord toont standen die nu allemaal op nul staan — direct bijwerken, anders
  // wijst het gepinde bericht het hele weekend nog naar de oude week.
  await updateWereldbord(client, true);
}

// ── Startup: los testkanaal-namen op naar channel IDs ─────────────────────────
// Socket Mode events bevatten alleen een channel ID, geen channel_name.
// Door de IDs eenmalig op te zoeken werkt isTestKanaalCheck() direct na opstarten.

async function laadTestKanaalIds(client) {
  if (TEST_KANALEN.length === 0) return;
  try {
    let cursor;
    do {
      const res = await client.conversations.list({
        types: 'public_channel,private_channel',
        limit: 200,
        cursor,
      });
      for (const ch of res.channels || []) {
        if (TEST_KANALEN.includes(ch.name)) {
          voegTestKanaalToe(ch.id);
          console.log(`🧪 Testkanaal geladen: #${ch.name} → ${ch.id}`);
        }
      }
      cursor = res.response_metadata?.next_cursor;
    } while (cursor);
  } catch (err) {
    console.warn(`⚠️ Testkanaal-IDs niet geladen (${err.message}) — worden geleerd via eerste slash command.`);
  }
}

// ── Dagelijkse JSON backup ─────────────────────────────────────────────────────
// Kopieert alle data-bestanden naar backups/ met datumstempel.
// Houdt de laatste 7 backups per dag — oudere worden automatisch verwijderd.





// ── Kroket van de Dag ─────────────────────────────────────────────────────────

const loadKroketVanDeDag  = () => readJSON('kroket_van_de_dag.json', {});
const saveKroketVanDeDag  = (data) => writeJSON('kroket_van_de_dag.json', data);

// Leest de reacties van gisteren's poll en genereert uitslag + nieuw voorstel.
async function voerKroketVanDeDagUit(client, channelId = process.env.SLACK_CHANNEL_ID) {
  const kanaal = channelId;
  // In een testkanaal: alleen genereren + posten, GEEN gedeelde dagstaat lezen/schrijven
  // (anders vervuilt een test de echte dagcyclus van het hoofdkanaal).
  const isTest = isTestKanaalCheck(channelId);
  const gisteren = loadKroketVanDeDag();

  // ── Stap 1: uitslag van gisteren — krokant of slap korstje ────────────────
  if (!isTest && gisteren.ts && gisteren.naam) {
    let krokant = 0, slap = 0;
    try {
      const res = await client.reactions.get({ channel: kanaal, timestamp: gisteren.ts, full: true });
      const reacties = res.message?.reactions || [];
      krokant = reacties.find(r => r.name === 'bread')?.count || 0;
      slap    = reacties.find(r => r.name === 'skull')?.count || 0;
      if (krokant > 0) krokant--; // bot's eigen reactie eraf
      if (slap > 0)    slap--;
    } catch (_) {}

    const totaal     = krokant + slap;
    const goedgekeurd = krokant >= slap;
    const percentageKrokant = totaal > 0 ? Math.round((krokant / totaal) * 100) : 0;
    // Reageerde niemand, dan is er geen oordeel — alleen een gelijkstand van nul. `krokant >= slap`
    // is bij 0-0 waar, dus zonder deze vlag was "krokant" het stille standaardoordeel en was
    // `/kroketgod gok krokant` elke werkdag een gegarandeerde +2 punten (en +2 roem) zolang
    // niemand op de dagkroket reageerde. De uitslag wordt nog wél verkondigd; alleen de gok
    // wordt niet afgerekend en de inzetten blijven onaangeroerd.
    const geenOordeel = totaal === 0;

    const uitslagPrompt = `Geen inleidingszin. Verkondig de officiële uitslag van de Kroket van de Dag-stemming.
De kroket in kwestie: "${gisteren.naam}".
Stemresultaat: ${krokant}x 🥖 Krokant en ${slap}x 💀 Slap korstje (totaal: ${totaal} stemmen, ${percentageKrokant}% krokant).
Officieel oordeel: ${geenOordeel ? 'GEEN OORDEEL — er is niet één stem uitgebracht' : goedgekeurd ? 'KROKANT — toegelaten tot de frituur' : 'SLAP KORSTJE — teruggestuurd naar de snack-hel'}.
${geenOordeel ? 'Spreek uw teleurstelling uit over het volledige uitblijven van stemmen: de kroket is onbeoordeeld gebleven en wordt in de wachtkamer van de frituur gezet. Er vallen geen punten.' : 'Sluit af met maximaal één droge zin als goddelijke conclusie over dit collectieve oordeel.'}
Gebruik het decreet- of spoedmelding-formaat. Maximaal 5 regels hoofdtekst.`;

    // Vangnet: deze aanroep stond buiten élke try. Viel de LLM-keten om op het dagquota, dan
    // aborteerde voerKroketVanDeDagUit hier — en dan was er die dag geen uitslag, geen
    // gok-afrekening én geen nieuwe Kroket van de Dag (dus ook geen gok mogelijk). Eén
    // ongeguarde call sloopte de hele dagcyclus; stap 2 hieronder had dat vangnet al wel.
    const uitslagTekst = schoonOutput(await kroketResponseMetVangnet(uitslagPrompt, 350, false,
      geenOordeel
        ? `⚖️ *DE UITSPRAAK BLIJFT UIT* ⚖️\n\n> Over *${gisteren.naam}* is niet één stem uitgebracht. De Hoge Frituurraad kan geen oordeel vellen over een kroket die niemand heeft aanschouwd.\n> Er vallen geen punten.\n\n— De Hoge Frituurraad`
        : `⚖️ *HET OORDEEL OVER ${gisteren.naam.toUpperCase()}* ⚖️\n\n> ${krokant}× 🥖 krokant tegen ${slap}× 💀 slap korstje (${percentageKrokant}% krokant).\n> Officieel oordeel: *${goedgekeurd ? 'KROKANT — toegelaten tot de frituur' : 'SLAP KORSTJE — teruggestuurd naar de snack-hel'}*.\n\n— De Hoge Frituurraad`));
    await postToChannel(client, kanaal, uitslagTekst);
    voegKennisToe('kroket-uitslag', `"${gisteren.naam}" ${goedgekeurd ? 'krokant (toegelaten)' : 'slap korstje (afgekeurd)'} — ${krokant}x krokant, ${slap}x slap`, 'Kroket van de Dag');

    // ── Kroket-gok afrekenen: wie het oordeel juist voorspelde krijgt +2 ──────
    try {
      const gokData = readJSON('kroketgok.json', {});
      if (geenOordeel && gokData.ts === gisteren.ts && Object.keys(gokData.gokken || {}).length > 0) {
        // Geen oordeel, dus geen winnaars en geen verliezers. De gokken blijven staan zodat de
        // volgende afrekening ze niet nog eens tegenkomt; de melding is stil (ephemeral bestaat
        // hier niet) maar wel expliciet in het kanaal, anders lijkt de gok verdwenen.
        await postToChannel(client, kanaal,
          `🔮 *DE VOORSPELLERS* 🔮\n\n> Er is geen oordeel geveld over *${gisteren.naam}* — niemand stemde. ` +
          `De ${Object.keys(gokData.gokken).length} voorspelling(en) vervallen zonder gevolg.\n\n— De Hoge Frituurraad`);
      } else if (gokData.ts === gisteren.ts && gokData.gokken && Object.keys(gokData.gokken).length > 0) {
        const juist = goedgekeurd ? 'krokant' : 'slap';
        const gokMembers = loadMembers();
        const winnaars = Object.entries(gokData.gokken).filter(([, k]) => k === juist).map(([id]) => id);
        const totaalGok = Object.keys(gokData.gokken).length;
        const uitgesteldeZegens = [];
        for (const winnaarId of winnaars) {
          await pasScoreAanMetCheck(client, winnaarId, 2, { channelId: kanaal, uitgesteldeZegens });
          logGebeurtenis('kroketgok', winnaarId, `${gokMembers[winnaarId]?.bijnaam || winnaarId} voorspelde het oordeel over "${gisteren.naam}" juist (+2)`);
        }
        const namen = winnaars.map(id => gokMembers[id]?.bijnaam || id);
        const gokTekst = winnaars.length > 0
          ? `🔮 *DE VOORSPELLERS* 🔮\n\n> *${namen.join('*, *')}* voorspelde${winnaars.length > 1 ? 'n' : ''} het oordeel juist ` +
            `(${totaalGok} voorspelling${totaalGok > 1 ? 'en' : ''} totaal) — *+2 kroketpunten* elk.\n\n— De Hoge Frituurraad`
          : `🔮 *DE VOORSPELLERS* 🔮\n\n> ${totaalGok} volgeling${totaalGok > 1 ? 'en waagden' : ' waagde'} een voorspelling — ` +
            `allen zaten ernaast. Het vet laat zich niet lezen.\n\n— De Hoge Frituurraad`;
        await postToChannel(client, kanaal, gokTekst);
        for (const post of uitgesteldeZegens) await post();
      }
      writeJSON('kroketgok.json', {});
    } catch (err) {
      console.error('⚠️ Kroket-gok afrekenen mislukt:', err.message);
    }
  }

  // ── Stap 2: nieuwe kroket genereren — een gek maar ECHT eetbaar twijfelgeval ─
  const eerdereNamen = (gisteren.geschiedenis || []).slice(-10).join(', ');
  const kroketSystemBericht = 'Je bent een creatieve schrijver die gewaagde, niet-bestaande maar ÉCHT eetbare Nederlandse kroketvarianten verzint. Je geeft ALTIJD exact het gevraagde formaat terug — niets meer, niets minder. Geen uitleg, geen preamble, geen vragen.';
  const kroketInstructie =
    `Verzin één niet-bestaande maar ÉCHT eetbare kroketsoort: een gewaagde, gekke combinatie van bestaande gerechten, keukens of smaken waarvan je oprecht NIET weet of het briljant of een ramp is — een echt twijfelgeval voor de stemming "krokant of slap korstje".\n\n` +
    `HARDE REGELS:\n` +
    `- Het moet écht eetbaar en voorstelbaar zijn. ABSOLUUT GEEN gif, dood, ziekte, "op eigen risico", bedorven, gevaarlijke of niet-eetbare ingrediënten — dan is het geen keuze maar een grap.\n` +
    `- Wel wild en onverwacht: combineer bestaande gerechten/keukens op een verrassende manier (denk aan: kapsalon-kroket, sushi-kroket, stroopwafel-met-oude-kaas, ramen-kroket, speculaas-brie, pindakaas-sambal-banaan).\n` +
    `- De twijfel zit in de gedurfde SMAAKCOMBINATIE, niet in gevaar.` +
    (eerdereNamen ? ` Gebruik GEEN van deze namen: ${eerdereNamen}.` : '') +
    `\n\nGeef PRECIES dit terug:\nNAAM: [grappige naam voor de combinatie, max 6 woorden]\nBESCHRIJVING: [twee droge, grappige zinnen die de combinatie beschrijven en oprechte twijfel oproepen of dit krokant-waardig is of een slap korstje]`;

  const KROKET_FALLBACKS = [
    { naam: 'De Kapsalon-kroket', beschrijving: 'Shoarma, friet, knoflooksaus en gesmolten kaas, samengeperst tot één frituurbare eenheid. Hoogstandje van efficiëntie, of een snackbar die instortte tot een bal?' },
    { naam: 'De Stroopwafel-Oude Kaas Kroket', beschrijving: 'Karamelstroop en scherpe belegen kaas, samen in één korst. Zoet ontmoet zout op een manier die geniaal is, of een ruzie tussen twee smaken die nooit hadden mogen daten.' },
    { naam: 'De Ramen-kroket', beschrijving: 'Ingedikte ramenbouillon, een lopend eitje en noedels, gevangen in paneer. Comfortabel genie, of een soep die nóg een keer dezelfde fout maakt.' },
    { naam: 'De Pindakaas-Sambal-Banaan Kroket', beschrijving: 'Romige pindakaas, brandende sambal en zoete banaan — een Surinaamse koortsdroom in korst. Briljant drieluik, of een weddenschap die te ver ging.' },
    { naam: 'De Speculaas-Brie Kroket', beschrijving: 'Warme kruidige speculaas om een hart van smeltende brie. Kerst in één hap, of een dessert dat per ongeluk in de frituurpan viel.' },
  ];

  let naam = 'De Mysterieuze Dagkroket';
  let beschrijving = 'Een gewaagde combinatie waar de frituur nog over twijfelt.';

  const parseerKroketOutput = (raw) => {
    const naamMatch = raw.match(/NAAM:\s*(.+)/i);
    const beschMatch = raw.match(/BESCHRIJVING:\s*([\s\S]+)/i);
    const n = naamMatch?.[1]?.trim().replace(/^[*_]+|[*_]+$/g, '') || '';
    const b = beschMatch?.[1]?.trim().replace(/\n/g, ' ').replace(/^[*_]+|[*_]+$/g, '') || '';
    if (n && !n.includes('?') && n.length < 80 && b.length > 10) return { naam: n, beschrijving: b };
    return null;
  };

  // Door de gewone keten, niet meer rechtstreeks Gemini en dan Groq: zo telt hij mee op de
  // LLM-meter, slaat hij gebankte of overbelaste schakels over en heeft hij meer dan twee kansen.
  // Een antwoord in het verkeerde formaat schuift door naar het volgende model (valideer).
  // Geen karakterkeuring: dit is een stramien, geen uitspraak van de Kroket God.
  try {
    const rauw = await _draaiModellen([
      { role: 'system', content: kroketSystemBericht },
      { role: 'user',   content: kroketInstructie },
    ], 350, 'slim', { keurKarakter: false, valideer: t => !!parseerKroketOutput(t) });
    const parsed = parseerKroketOutput(rauw || '');
    if (!parsed) throw new Error('ongeldig formaat');
    naam = parsed.naam; beschrijving = parsed.beschrijving;
  } catch (err) {
    console.warn('⚠️ Kroket van de dag: geen bruikbaar antwoord uit de keten, gebruik fallback:', err.message);
    const fb = KROKET_FALLBACKS[Math.floor(Math.random() * KROKET_FALLBACKS.length)];
    naam = fb.naam; beschrijving = fb.beschrijving;
  }

  // ── Stap 3: poll-bericht plaatsen — krokant of slap korstje ───────────────
  const pollTekst =
    `⚜️ KROKET VAN DE DAG ⚜️\n\n` +
    `*${naam}*\n` +
    `> ${beschrijving}\n\n` +
    `Verdient deze de frituur? Stem nu:\n` +
    `🥖 *Krokant* — deze mag de frituur in\n` +
    `💀 *Slap korstje* — terug naar de snack-hel\n\n` +
    `🔮 _Waag ook een voorspelling van het eindoordeel: \`/kroketgod gok krokant\` of \`/kroketgod gok slap\` — juist voorspeld is *+2 kroketpunten* bij de uitslag._\n\n` +
    `— De Almachtige Kroket God :lekker_kroketje:`;

  let pollTs = null;
  try {
    const msg = await client.chat.postMessage({ channel: kanaal, text: pollTekst });
    pollTs = msg.ts;
    await client.reactions.add({ channel: kanaal, timestamp: pollTs, name: 'bread' });
    await client.reactions.add({ channel: kanaal, timestamp: pollTs, name: 'skull' });
  } catch (err) {
    console.error('⚠️ Kroket van de dag post mislukt:', err.message);
    return;
  }

  // ── Stap 4: opslaan (niet in een testkanaal — staat van het hoofdkanaal blijft intact) ──
  if (!isTest) {
    const nieuweGeschiedenis = [...(gisteren.geschiedenis || []), naam].slice(-30);
    saveKroketVanDeDag({ ts: pollTs, naam, beschrijving, datum: new Date().toISOString().slice(0, 10), geschiedenis: nieuweGeschiedenis });
  }
  console.log(`✅ Kroket van de dag${isTest ? ' (test)' : ''}: "${naam}"`);
}

// Dagelijks om 09:45 op werkdagen — na de andere 09:xx crons
planCron('45 9 * * 1-5', async () => {
  try { await voerKroketVanDeDagUit(app.client); }
  catch (err) { console.error('⚠️ Kroket van de dag cron mislukt:', err.message); }
}, { timezone: 'Europe/Amsterdam' });

// ── Kroket Quiz ───────────────────────────────────────────────────────────────

const loadQuiz = () => readJSON('quiz.json', {});
const saveQuiz = (data) => writeJSON('quiz.json', data);

// Controleert via AI of een gegeven antwoord inhoudelijk klopt (spelfouten OK)
async function isJuistAntwoord(gegeven, juist, vraag) {
  const uit = await classificeer(
    'Antwoord ALLEEN met JA of NEE. Geen uitleg.',
    `Vraag: "${vraag}"\nCorrect antwoord: "${juist}"\nGegeven antwoord: "${gegeven}"\n` +
    `Is het gegeven antwoord inhoudelijk correct? Kleine spelfouten en synoniemen zijn OK. Antwoord JA of NEE.`,
    // Vangnet 'nee': bij een storing geen punt toekennen voor een antwoord dat niemand heeft
    // nagekeken. Fail-closed, net als bij de bingo-claim.
    { klassen: ['ja', 'nee'], vangnet: 'nee', maxTokens: 5 },
  );
  return uit === 'ja';
}

async function genereerEnPostQuiz(client, channelId = process.env.SLACK_CHANNEL_ID) {
  const kanaal = channelId;
  const bestaande = loadQuiz();
  if (bestaande.ts && !bestaande.afgerond) {
    console.log('⚠️ Actieve quiz aanwezig — eerst onthullen voor een nieuwe.');
    return;
  }

  // Haal een triviavraag op via Open Trivia Database en vertaal naar Nederlands
  const triviaRuw = await haalTriviaVraag();

  let vraag = '', antwoord = '', uitleg = '';
  // Beide calls hieronder door de keten (niveau 'licht', zonder karakterkeuring): eerst stonden
  // ze rechtstreeks op Groq — één provider, geen terugval, niet op de LLM-meter.
  const heeftQuizFormaat = (t) => /VRAAG:\s*\S/i.test(t) && /ANTWOORD:\s*\S/i.test(t);

  if (triviaRuw) {
    try {
      const raw = await _draaiModellen([
        { role: 'system', content: 'Vertaal naar correct Nederlands. Geef ALLEEN het gevraagde formaat terug.' },
        { role: 'user', content:
          `Vertaal deze triviavraag naar het Nederlands:\nVraag: "${triviaRuw.vraag}"\nAntwoord: "${triviaRuw.juist}"\nCategorie: "${triviaRuw.categorie}"\n\n` +
          `Geef PRECIES dit terug:\nVRAAG: [vertaalde vraag]\nANTWOORD: [vertaald antwoord, max 5 woorden]\nUITLEG: [korte uitleg waarom dit het antwoord is, 1-2 zinnen in het Nederlands]`
        },
      ], 200, 'licht', { temperatuur: 0.3, keurKarakter: false, valideer: heeftQuizFormaat }) || '';
      vraag    = raw.match(/VRAAG:\s*(.+)/i)?.[1]?.trim()       || '';
      antwoord = raw.match(/ANTWOORD:\s*(.+)/i)?.[1]?.trim()    || '';
      uitleg   = raw.match(/UITLEG:\s*([\s\S]+)/i)?.[1]?.trim() || '';
    } catch (err) {
      console.warn('⚠️ Vertaling mislukt, gebruik Engelse versie:', err.message);
      vraag    = triviaRuw.vraag;
      antwoord = triviaRuw.juist;
      uitleg   = `Categorie: ${triviaRuw.categorie}.`;
    }
  }

  // Fallback: kroket-vraag via de keten als de trivia-API faalt
  if (!vraag || !antwoord) {
    console.warn('⚠️ Trivia API mislukt, genereer kroketvraag via AI');
    try {
      const raw = await _draaiModellen([
        { role: 'system', content: 'Je bent een quizmaster. Geef ALLEEN het gevraagde formaat terug.' },
        { role: 'user', content:
          `Verzin een Nederlandse triviavraag over kroketten, snackcultuur of Nederlandse eetgewoonten.\n` +
          `VRAAG: [de vraag]\nANTWOORD: [max 5 woorden]\nUITLEG: [1-2 zinnen uitleg]`
        },
      ], 200, 'licht', { temperatuur: 0.95, keurKarakter: false, valideer: heeftQuizFormaat }) || '';
      vraag    = raw.match(/VRAAG:\s*(.+)/i)?.[1]?.trim()       || '';
      antwoord = raw.match(/ANTWOORD:\s*(.+)/i)?.[1]?.trim()    || '';
      uitleg   = raw.match(/UITLEG:\s*([\s\S]+)/i)?.[1]?.trim() || '';
    } catch (err) {
      console.error('⚠️ Quiz generatie volledig mislukt:', err.message);
      return;
    }
  }

  if (!vraag || !antwoord) { console.error('⚠️ Quiz formaat ongeldig'); return; }

  // Post quiz in karakter — prikkelend, niet te formeel
  const quizPrompt =
    `Geen inleidingszin. Stel de volgende triviavraag als een heilige uitdaging aan de Heren van de Kroket Illuminati. ` +
    `Vraag: "${vraag}". ` +
    `Regels: antwoorden gaan in de *thread* — het eerste juiste antwoord wint kroketpunten, latere juiste antwoorden ook maar minder. ` +
    `Maak de aankondiging kort, scherp en uitdagend — wek nieuwsgierigheid zonder de vraag te beantwoorden of hints te geven. ` +
    `Gebruik spoedmelding- of decreet-formaat. Absoluut max 4 regels hoofdtekst.`;

  const quizTekst = schoonOutput(await kroketResponse(quizPrompt, 300, false));
  const quizBericht = `${quizTekst}\n\n_Antwoord in de thread 👇 — eerste juiste antwoord wint meeste punten._`;
  let pollTs = null;
  try {
    const msg = await client.chat.postMessage({ channel: kanaal, text: quizBericht });
    pollTs = msg.ts;
  } catch (err) {
    console.error('⚠️ Quiz post mislukt:', err.message);
    return;
  }

  const deadline = new Date(Date.now() + 4 * 60 * 60 * 1000).toISOString();
  saveQuiz({ ts: pollTs, channel: kanaal, vraag, antwoord, uitleg, gepost: new Date().toISOString(), deadline, afgerond: false });
  console.log(`✅ Quiz gepost: "${vraag}" — antwoord: "${antwoord}"`);
}

async function onthulQuiz(client) {
  const quiz = loadQuiz();
  if (!quiz.ts || quiz.afgerond) { console.log('Geen actieve quiz.'); return; }

  // Lees alle thread-replies, sorteer op tijd, filter bot-berichten
  let replies = [];
  try {
    const res = await client.conversations.replies({ channel: quiz.channel, ts: quiz.ts, limit: 200 });
    replies = (res.messages || [])
      .filter(m => m.ts !== quiz.ts && !m.bot_id && !m.bot_profile)
      .sort((a, b) => parseFloat(a.ts) - parseFloat(b.ts));
  } catch (err) {
    console.error('⚠️ Thread lezen mislukt:', err.message);
    return;
  }

  // Zoek ALLE juiste antwoorden op volgorde van tijd
  const members = loadMembers();
  const juisteAntwoorders = []; // [{ userId, tekst }, ...] gesorteerd op tijd

  for (const reply of replies) {
    const tekst = (reply.text || '').replace(/<@[^>]+>/g, '').trim();
    if (!tekst) continue;
    // Alleen leden, en geen ballingen. Dit ontbrak: elke gast in het kanaal die het juiste antwoord
    // in de thread zette kreeg kroketpunten én EEUWIGE roem, en een balling kon zo gewoon
    // doorspelen. Elke andere spelactie toetst dit wel — de quiz was het gat, juist omdat de
    // deelname hier niet via een commando loopt maar via een gewoon threadbericht.
    if (!members[reply.user]) continue;
    if (isVerbannen(reply.user)) continue;
    // Sla dubbele gebruikers over — alleen eerste antwoord per persoon telt
    if (juisteAntwoorders.some(w => w.userId === reply.user)) continue;
    if (await isJuistAntwoord(tekst, quiz.antwoord, quiz.vraag)) {
      juisteAntwoorders.push({ userId: reply.user, tekst });
    }
  }

  // Eerst vastleggen dat de quiz afgerond is, DAARNA uitbetalen. Andersom ging het mis: de
  // punten waren geboekt maar `afgerond` werd pas ná de LLM-onthulling opgeslagen, en die kan
  // op het dagquota omvallen. De cron van 16:00 vond de quiz dan de volgende dag nog open en
  // betaalde exact dezelfde winnaars opnieuw. Het Verhoor doet het al in deze orde (zie
  // onthulVerhoor: "eerst vastleggen: dubbele onthulling is dubbele punten").
  quiz.afgerond = true;
  saveQuiz(quiz);

  // Punten uitdelen: eerste = 2 punten, rest = 1 punt
  const naspel = maakNaspel(juisteAntwoorders.map(w => w.userId));
  for (let i = 0; i < juisteAntwoorders.length; i++) {
    const { userId } = juisteAntwoorders[i];
    const punten = i === 0 ? 2 : 1;
    await pasScoreAanMetCheck(client, userId, punten, { naspel });
  }

  // Reveal-bericht in de thread
  let onthulPrompt;
  if (juisteAntwoorders.length > 0) {
    const eerste = juisteAntwoorders[0];
    const eersteBijnaam = members[eerste.userId]?.bijnaam || 'een onbekende volgeling';
    const overigen = juisteAntwoorders.slice(1).map(w => members[w.userId]?.bijnaam || 'een volgeling');

    voegKennisToe('quiz-winnaar', `${eersteBijnaam} won een quiz op vraag: "${quiz.vraag}"`, eersteBijnaam);

    const overigenZin = overigen.length > 0
      ? ` Ook ${overigen.join(', ')} had${overigen.length > 1 ? 'den' : ''} het goed en ontvangt elk 1 kroketpunt.`
      : '';

    onthulPrompt =
      `Geen inleidingszin. Onthul het antwoord van de heilige triviavraag. ` +
      `Vraag: "${quiz.vraag}". Correct antwoord: "${quiz.antwoord}". Uitleg: "${quiz.uitleg}". ` +
      `${eersteBijnaam} was de eerste met het juiste antwoord en ontvangt 2 kroketpunten — noem deze naam letterlijk.` +
      `${overigenZin} ` +
      `Gebruik het decreet-formaat. Max 5 regels.`;
  } else {
    onthulPrompt =
      `Geen inleidingszin. Onthul het antwoord van de heilige triviavraag — niemand had het goed. ` +
      `Vraag: "${quiz.vraag}". Correct antwoord: "${quiz.antwoord}". Uitleg: "${quiz.uitleg}". ` +
      `Reageer met teleurstelling over het collectieve kennisniveau van de Illuminati. Max 4 regels.`;
  }

  const onthulTekst = schoonOutput(await kroketResponse(onthulPrompt, 400, false));
  await client.chat.postMessage({ channel: quiz.channel, thread_ts: quiz.ts,
    text: onthulTekst + naspelMenties(naspel) });
  // De onthulling hangt zelf al in de quiz-thread, dus het naspel gaat daar netjes onder.
  await postNaspel(client, quiz.channel, quiz.ts, naspel);
  console.log(`✅ Quiz onthuld. ${juisteAntwoorders.length} correct — eerste: ${juisteAntwoorders[0]?.userId || 'niemand'}`);
}

// Cron: maandag, woensdag, donderdag om 10:15 — quiz posten
planCron('15 10 * * 1,3,4', async () => {
  try { await genereerEnPostQuiz(app.client); }
  catch (err) { console.error('⚠️ Quiz cron mislukt:', err.message); }
}, { timezone: 'Europe/Amsterdam' });

// Cron: dagelijks 16:00 — onthul quiz als deadline verstreken is
planCron('0 16 * * 1-5', async () => {
  try {
    const quiz = loadQuiz();
    if (!quiz.ts || quiz.afgerond) return;
    if (new Date() >= new Date(quiz.deadline)) await onthulQuiz(app.client);
  } catch (err) { console.error('⚠️ Quiz onthul cron mislukt:', err.message); }
}, { timezone: 'Europe/Amsterdam' });

// ══════════════════════════════════════════════════════════════════════════════
// DE HOGE FRITUURRAAD — jurisprudentie
// ══════════════════════════════════════════════════════════════════════════════
// Het bestaande `rechtbank [A] vs [B]`-commando was eenmalig theater: de Kroket God sprak een
// vonnis en dat was daarna weg. Nu krijgt elk vonnis een ZAAKNUMMER en wordt het bewaard — en bij
// een volgende zaak haalt de BM25-index van Het Grote Archief de vergelijkbare vonnissen op, die de
// God in zijn uitspraak MOET aanhalen.
//
// Daardoor ontstaat er een rechtsstelsel dat niemand heeft ontworpen: "conform de zaak
// Kroketinho/KroketPet, 2026/III". Elke uitspraak verhoudt zich tot de vorige, en na een paar
// maanden heeft het genootschap een eigen rechtsleer met precedenten die de leden zelf hebben
// veroorzaakt.
//
// BEWUST GEEN PUNTEN OF STRAFFEN. Er zijn al twee wegen voor echte gevolgen (de gele kaart met
// stemming, en het tribunaal). Een derde weg met sancties zou die twee ondermijnen en van een grap
// een machtsmiddel maken. Dit is de civiele, ceremoniële tak: de uitspraak zélf is de inzet.
//
// ÉÉN ZAAK PER AANKLAGER PER DAG. Elk vonnis is voorgoed precedent, dus zonder rem zou één lid op
// één middag de hele rechtsleer kunnen schrijven.

const JURISPRUDENTIE_BESTAND = 'jurisprudentie.json';
const loadJurisprudentie = () => readJSON(JURISPRUDENTIE_BESTAND, { zaken: [], laatsteZaak: {} });
const saveJurisprudentie = (data) => writeJSON(JURISPRUDENTIE_BESTAND, data);

// Hoeveel vonnissen we in het overzicht bewaren. Het archief houdt ze allemaal (en dat is de bron
// voor de precedenten); dit bestand is het register en mag begrensd blijven.
const JURISPRUDENTIE_MAX = 100;
const ZAAK_COOLDOWN_MS = 20 * 3_600_000; // ~een dag, maar niet op de klok van middernacht

// Voert een zaak. Geeft { ok, tekst } terug; bij ok plaatst hij zelf het vonnis in het kanaal.
async function voerZaak(client, aanklagerId, invoer, channelId) {
  const ontleed = parseerZaak(invoer);
  if (ontleed.fout) return { ok: false, tekst: `_${ontleed.fout}_` };

  const data = loadJurisprudentie();
  const laatste = data.laatsteZaak?.[aanklagerId] || 0;
  if (Date.now() - laatste < ZAAK_COOLDOWN_MS) {
    const rest = resterendeTijd(ZAAK_COOLDOWN_MS - (Date.now() - laatste));
    return { ok: false, tekst: `_De Raad behandelt één zaak per aanklager per dag. Uw volgende zittingsuur begint over ${rest}._` };
  }

  // Namen naar leden herleiden waar mogelijk; een buitenstaander mag ook partij zijn (zoals het
  // oude commando ook toestond) maar wordt als zodanig benoemd.
  const g1 = getMemberByNaam(ontleed.partij1);
  const g2 = getMemberByNaam(ontleed.partij2);
  const partij1 = g1 ? g1[1].bijnaam : `Buitenstaander "${ontleed.partij1}"`;
  const partij2 = g2 ? g2[1].bijnaam : `Buitenstaander "${ontleed.partij2}"`;
  if (g1 && g2 && g1[0] === g2[0]) {
    return { ok: false, tekst: '_Een zaak tegen uzelf is geen zaak maar een gewetenskwestie._' };
  }

  const jaar = new Date().getFullYear();
  const nummer = zaakNummer(jaar, volgendeTeller(data.zaken, jaar));

  // Precedenten: zoek in het archief naar eerdere VONNISSEN die op deze zaak lijken. De grond
  // weegt het zwaarst, maar de partijnamen doen ook mee — een eerdere zaak tussen dezelfde twee
  // is per definitie relevant.
  const zoekterm = [ontleed.grond, partij1, partij2].filter(Boolean).join(' ');
  const precedenten = zoekArchief(zoekterm, { n: 3, soort: 'vonnis', minLengte: 20 });
  const precedentBlok = precedenten.length
    ? `\n\n${wrapOnvertrouwd(
        'EERDERE VONNISSEN VAN DE RAAD (precedenten). Haal er MINSTENS ÉÉN expliciet aan bij zaaknummer, ' +
        'en verhoud je uitspraak ertoe: volg het precedent, of wijk er beargumenteerd van af',
        precedenten.map(p => p.tekst).join('\n\n'))}`
    : '\n\nEr zijn nog geen precedenten: dit is een zaak van de eerste soort. Zeg dat expliciet — de Raad vestigt hier nieuw recht.';

  const grondZin = ontleed.grond
    ? `De grond van de aanklacht: "${ontleed.grond}".`
    : 'De grond van de aanklacht is niet nader omschreven; benoem dat en leid hem zelf af uit de snackleer.';

  const vonnis = await kroketResponseMetVangnet(
    `Je bent de Hoge Frituurraad en spreekt vonnis in zaak ${nummer}: ${partij1} tegen ${partij2}. ${grondZin}\n\n` +
    `EISEN:\n` +
    `- Begin met "*ZAAK ${nummer} — ${partij1} / ${partij2}*" en niets daarvoor.\n` +
    `- Spreek beide partijen uitsluitend aan bij hun exacte naam: "${partij1}" en "${partij2}".\n` +
    `- Structuur: de aanklacht (1 zin), het verweer (1 zin), de overweging (1-2 zinnen, verwijs naar de Geboden of de snackleer), het vonnis (1-2 zinnen).\n` +
    `- Er is een winnende en een verliezende partij. Geen gelijkspel, geen ontwijking.\n` +
    `- Leg GEEN kroketpunten, straffen of verbanningen op — de Raad spreekt hier recht, geen sancties.\n` +
    `- Juridische, plechtige taal. Geen inleidingszin.` +
    precedentBlok,
    700, false,
    `⚖️ *ZAAK ${nummer} — ${partij1} / ${partij2}*\n\n> De Raad heeft de zaak gehoord, maar het Vetbad is te onrustig voor een volwaardig vonnis. ` +
    `De zaak wordt aangehouden en het nummer blijft gereserveerd.\n\n— De Hoge Frituurraad`
  );

  const zaak = {
    nummer, jaar, ts: Date.now(),
    aanklagerId,
    partij1, partij2,
    partij1Id: g1 ? g1[0] : null,
    partij2Id: g2 ? g2[0] : null,
    grond: ontleed.grond || null,
    tekst: vonnis,
  };
  data.zaken = [...(data.zaken || []), zaak].slice(-JURISPRUDENTIE_MAX);
  data.laatsteZaak = { ...(data.laatsteZaak || {}), [aanklagerId]: Date.now() };
  saveJurisprudentie(data);

  // Naar het archief met soort 'vonnis', zodat de BM25-index hem bij een volgende zaak als
  // precedent kan opdiepen. Het zaaknummer staat vooraan in de tekst — zonder dat kan een
  // volgend vonnis er niet naar verwijzen, en dan is het geen precedent maar een anekdote.
  voegToeAanArchief({
    soort: 'vonnis', spreker: 'De Hoge Frituurraad', sprekerId: null,
    tekst: `Zaak ${nummer} (${partij1} tegen ${partij2}${ontleed.grond ? `, over ${ontleed.grond}` : ''}): ` +
      `${stripSlackOpmaak(vonnis, 380)}`,
  });
  logGebeurtenis('zaak', g1 ? g1[0] : null, `Zaak ${nummer}: ${partij1} tegen ${partij2}${ontleed.grond ? ` over ${ontleed.grond}` : ''}`, null, aanklagerId);

  await postToChannel(client, channelId, vonnis);
  return { ok: true, tekst: `_Zaak ${nummer} is gewezen en opgenomen in de jurisprudentie._`, nummer };
}

registreerFeature({
  naam: 'jurisprudentie',
  state: [JURISPRUDENTIE_BESTAND],
  help: [
    { gebruik: '/kroketgod rechtbank [naam1] vs [naam2] (over [grond])', verwacht: 'de Hoge Frituurraad wijst vonnis; elke uitspraak krijgt een zaaknummer en wordt precedent voor de volgende (1 zaak per dag)' },
    { gebruik: '/kroketgod jurisprudentie', verwacht: 'het register van gewezen zaken (`zaak [nummer]` voor de volledige uitspraak)' },
  ],
});

// ══════════════════════════════════════════════════════════════════════════════
// DE TIJDCAPSULE — voorspellingen verzegelen en later afrekenen
// ══════════════════════════════════════════════════════════════════════════════
// Een lid verzegelt een voorspelling met een moment: `voorspel over 2 weken de bamischijf valt`.
// Op dat moment ontzegelt de Kroket God hem en beoordeelt de Raad met emoji of het is uitgekomen.
// Uitgekomen = roem, want dit is vooruitzien en dat is blijvend; niet uitgekomen kost niets.
//
// WAAROM ROEM EN GEEN KROKETPUNTEN. De horizon is weken tot maanden. Kroketpunten resetten elke
// zondag, dus een beloning in punten zou afhangen van in welke week je capsule toevallig opengaat.
// Roem is de enige munt die net zo lang meegaat als de voorspelling zelf.
//
// WAAROM DE RAAD OORDEELT EN NIET DE LLM. "Is dit uitgekomen?" is precies het soort vraag waar een
// taalmodel met volle overtuiging naast zit, en het gaat over de werkelijkheid van de groep — die
// kennen de leden en het model niet. De emoji-stemming is bovendien gratis. Het patroon (stemmen
// pas bij SLUITING uitlezen met reactions.get) komt van de gele-kaart-poll: geen gemiste events,
// terugnemen telt automatisch, en er is geen eigen stemadministratie die kan gaan afwijken.
//
// TWEE FASEN IN ÉÉN DAGELIJKSE CRON: ontzegelen wat vervallen is, en beslechten wat al 24 uur
// openstaat. Volledig uit tijdstempels afgeleid, dus een dag downtime haalt zichzelf in.

const TIJDCAPSULE_BESTAND = 'tijdcapsule.json';
const loadCapsules = () => readJSON(TIJDCAPSULE_BESTAND, { items: [] });
const saveCapsules = (data) => writeJSON(TIJDCAPSULE_BESTAND, data);

const CAPSULE_JA = 'large_green_square';   // uitgekomen
const CAPSULE_NEE = 'large_red_square';    // niet uitgekomen
const CAPSULE_STEMUREN = 24;
const CAPSULE_ROEM = 3;
// Hoeveel capsules er per lid tegelijk verzegeld mogen staan. Zonder grens kan één lid de kalender
// volgooien en gaat er elke dag een capsule open — dan is het geen gebeurtenis meer.
const CAPSULE_MAX_OPEN = 3;
// Hoeveel er per dag hoogstens opengaan, zodat een stapel deadlines op dezelfde dag geen
// berichtenlawine wordt. De rest schuift een dag door; ze zijn toch al verlopen.
const CAPSULE_MAX_PER_DAG = 2;

function capsuleDatum(ts) {
  return new Date(ts).toLocaleDateString('nl-NL', {
    timeZone: 'Europe/Amsterdam', weekday: 'long', day: 'numeric', month: 'long',
  });
}

// Verzegelt een voorspelling. Geeft { ok, tekst } terug, net als de andere spelfuncties.
async function verzegelCapsule(client, userId, invoer) {
  const members = loadMembers();
  if (!members[userId]) return { ok: false, tekst: '_Alleen leden van de Kroket Illuminati mogen de toekomst bezweren._' };
  if (isVerbannen(userId)) return { ok: false, tekst: '_Een balling heeft geen zicht op de toekomst. Toon eerst berouw._' };

  const data = loadCapsules();
  const eigenOpen = (data.items || []).filter(c => c.userId === userId && c.status === 'verzegeld');
  if (eigenOpen.length >= CAPSULE_MAX_OPEN) {
    return { ok: false, tekst: `_U heeft al ${CAPSULE_MAX_OPEN} verzegelde voorspellingen openstaan. Wacht tot er één opengaat._` };
  }

  const ontleed = parseerWanneer(invoer);
  if (ontleed.fout) return { ok: false, tekst: `_${ontleed.fout}_` };

  const capsule = {
    id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    userId,
    tekst: ontleed.rest.slice(0, 400),
    label: ontleed.label,
    gemaakt: Date.now(),
    deadline: ontleed.deadline,
    status: 'verzegeld',
    kanaal: process.env.SLACK_CHANNEL_ID,
    berichtTs: null,
  };
  data.items = [...(data.items || []), capsule];
  saveCapsules(data);

  // Wél een kanaalbericht, en dat is met opzet: een voorspelling die niemand kent is later niet
  // te beoordelen, en de spanning zit er juist in dat de groep hem heeft zien verzegelen. De
  // INHOUD is dus openbaar; alleen het oordeel wacht.
  await postToChannel(client, capsule.kanaal,
    `⏳ *EEN TIJDCAPSULE IS VERZEGELD* ⏳\n\n> *${members[userId].bijnaam}* voorspelt:\n> _"${capsule.tekst}"_\n> Te openen ${capsuleDatum(capsule.deadline)} (${capsule.label}).\n\n` +
    `_Komt het uit, dan volgt ${CAPSULE_ROEM} roem. De Raad oordeelt straks._\n\n— De Hoge Frituurraad`);
  logGebeurtenis('capsule', userId, `${members[userId].bijnaam} verzegelde een voorspelling voor ${capsuleDatum(capsule.deadline)}`, capsule.tekst);
  return { ok: true, tekst: `_Verzegeld. De capsule gaat open op ${capsuleDatum(capsule.deadline)}._` };
}

// Fase 1: een vervallen capsule openen en de Raad laten stemmen.
async function ontzegelCapsule(client, capsule) {
  const members = loadMembers();
  const naam = members[capsule.userId]?.bijnaam || 'een verdwenen volgeling';
  const dagen = Math.max(1, Math.round((capsule.deadline - capsule.gemaakt) / 86_400_000));
  const bericht = await slackLimiter.schedule(() => client.chat.postMessage({
    channel: capsule.kanaal,
    text: 'Een tijdcapsule wordt ontzegeld',
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: '⏳ DE TIJDCAPSULE GAAT OPEN', emoji: true } },
      { type: 'section', text: { type: 'mrkdwn', text:
        `_${dagen} dag(en) geleden voorspelde *${naam}*:_\n\n> "${capsule.tekst}"\n\n*Is het uitgekomen?*` } },
      { type: 'context', elements: [{ type: 'mrkdwn', text:
        `:${CAPSULE_JA}: = uitgekomen · :${CAPSULE_NEE}: = niet uitgekomen · de Raad stemt ${CAPSULE_STEMUREN} uur · ` +
        `de voorspeller stemt niet mee · bij gelijkspel geen roem` }] },
    ],
  }));
  // De bot zet beide reacties voor, zodat er niets getypt hoeft te worden.
  for (const emoji of [CAPSULE_JA, CAPSULE_NEE]) {
    try {
      await slackLimiter.schedule(() => client.reactions.add({ channel: capsule.kanaal, timestamp: bericht.ts, name: emoji }));
    } catch (err) {
      console.warn(`⚠️ Capsule-reactie ${emoji} zetten mislukt:`, err.data?.error || err.message);
    }
  }
  return { berichtTs: bericht.ts, stemDeadline: Date.now() + CAPSULE_STEMUREN * 3_600_000 };
}

// Fase 2: stemmen uitlezen en beslechten. Zelfde uitleesregels als de gele-kaart-poll:
// botreacties, niet-leden en ballingen tellen niet, en wie op beide stemt stemt op niets.
async function beslechtCapsule(client, capsule) {
  const members = loadMembers();
  const uit = { ja: [], nee: [] };
  try {
    const res = await slackLimiter.schedule(() => client.reactions.get({
      channel: capsule.kanaal, timestamp: capsule.berichtTs, full: true,
    }));
    for (const r of res.message?.reactions || []) {
      const bak = r.name === CAPSULE_JA ? uit.ja : r.name === CAPSULE_NEE ? uit.nee : null;
      if (!bak) continue;
      for (const u of r.users || []) {
        if (u === BOT_USER_ID) continue;
        if (!members[u] || isVerbannen(u)) continue;
        // De voorspeller beoordeelt zijn eigen voorspelling niet.
        if (u === capsule.userId) continue;
        if (!bak.includes(u)) bak.push(u);
      }
    }
  } catch (err) {
    console.error('⚠️ Capsule-stemmen uitlezen mislukt:', err.data?.error || err.message);
    return null; // volgende ronde opnieuw proberen
  }
  const dubbel = uit.ja.filter(u => uit.nee.includes(u));
  uit.ja = uit.ja.filter(u => !dubbel.includes(u));
  uit.nee = uit.nee.filter(u => !dubbel.includes(u));

  const naam = members[capsule.userId]?.bijnaam || 'een verdwenen volgeling';
  const uitgekomen = uit.ja.length > uit.nee.length;
  const gelijk = uit.ja.length === uit.nee.length;
  let slot;
  if (gelijk) {
    slot = uit.ja.length === 0
      ? '> De Raad zweeg. Geen oordeel, geen roem — de capsule verdwijnt in het vet.'
      : `> De Raad staat gelijk (${uit.ja.length}–${uit.nee.length}). Geen oordeel, geen roem.`;
  } else if (uitgekomen) {
    slot = `> ✅ De Raad oordeelt met ${uit.ja.length}–${uit.nee.length}: *het is uitgekomen*. *${naam}* ontvangt *${CAPSULE_ROEM} roem*.`;
  } else {
    slot = `> ❌ De Raad oordeelt met ${uit.nee.length}–${uit.ja.length}: *het is niet uitgekomen*. Geen roem — maar de poging staat in de kronieken.`;
  }
  await postToChannel(client, capsule.kanaal,
    `⏳ *HET VONNIS OVER DE TIJDCAPSULE* ⏳\n\n> *${naam}* voorspelde: _"${capsule.tekst}"_\n${slot}\n\n— De Hoge Frituurraad`);

  // Elke stem is een daad: meestemmen over de voorspelling van een ander lid is precies het
  // gedrag dat De Voorspraak der Zachte Korst hoort te belonen.
  for (const stemmerId of new Set([...uit.ja, ...uit.nee])) {
    if (members[stemmerId]) await telActie(client, stemmerId, 'capsule_stem');
  }

  if (uitgekomen && members[capsule.userId]) {
    await pasRoemAan(client, capsule.userId, CAPSULE_ROEM);
    logGebeurtenis('capsule', capsule.userId, `${naam} voorspelde het juist en ontving ${CAPSULE_ROEM} roem`, capsule.tekst);
  }
  return { uitgekomen, gelijk, ja: uit.ja.length, nee: uit.nee.length };
}

// De dagelijkse klok over alle capsules. Volledig uit tijdstempels afgeleid.
async function verwerkCapsuleKlok(client) {
  const data = loadCapsules();
  const items = data.items || [];
  if (!items.length) return;
  const nu = Date.now();
  let gewijzigd = false;

  // Eerst beslechten: dat maakt ruimte en houdt de volgorde logisch (oude zaken eerst af).
  for (const c of items.filter(x => x.status === 'stemming' && x.stemDeadline && nu >= x.stemDeadline)) {
    const uitslag = await beslechtCapsule(client, c);
    if (!uitslag) continue; // uitlezen mislukt → volgende ronde opnieuw
    c.status = 'beslecht';
    c.uitkomst = uitslag;
    gewijzigd = true;
  }

  // Dan ontzegelen, met een dagplafond.
  const teOpenen = items
    .filter(x => x.status === 'verzegeld' && nu >= x.deadline)
    .sort((a, b) => a.deadline - b.deadline)
    .slice(0, CAPSULE_MAX_PER_DAG);
  for (const c of teOpenen) {
    // Een capsule van een lid dat het genootschap heeft verlaten wordt stil gesloten: er is
    // niemand meer om roem aan te geven, en de Raad hoeft er geen tijd aan te besteden.
    if (!loadMembers()[c.userId]) {
      c.status = 'vervallen';
      gewijzigd = true;
      continue;
    }
    const geopend = await ontzegelCapsule(client, c);
    if (!geopend) continue;
    c.status = 'stemming';
    c.berichtTs = geopend.berichtTs;
    c.stemDeadline = geopend.stemDeadline;
    gewijzigd = true;
  }

  if (gewijzigd) {
    // Beslechte capsules blijven staan als geschiedenis, maar begrensd.
    const beslecht = items.filter(x => x.status === 'beslecht' || x.status === 'vervallen').slice(-40);
    const open = items.filter(x => x.status === 'verzegeld' || x.status === 'stemming');
    saveCapsules({ items: [...beslecht, ...open] });
  }
}

registreerFeature({
  naam: 'tijdcapsule',
  state: [TIJDCAPSULE_BESTAND],
  help: [
    { gebruik: '/kroketgod voorspel [wanneer] [voorspelling]', verwacht: `verzegel een voorspelling — bijvoorbeeld \`voorspel over 2 weken de bamischijf valt\`. Komt hij uit, dan ${CAPSULE_ROEM} roem (max ${CAPSULE_MAX_OPEN} open, hoogstens ${MAX_HORIZON_DAGEN} dagen vooruit)` },
    { gebruik: '/kroketgod capsules', verwacht: 'alle verzegelde en beoordeelde tijdcapsules' },
  ],
  homeOrde: 40,
  home: ({ userId, members }) => {
    const items = (loadCapsules().items || []).filter(c => c.status === 'verzegeld' || c.status === 'stemming');
    if (!items.length) return [];
    const regels = items
      .sort((a, b) => a.deadline - b.deadline)
      .slice(0, 5)
      .map(c => `> ${c.userId === userId ? '*u*' : `*${members[c.userId]?.bijnaam || 'onbekend'}*`}: ` +
        `"${c.tekst.slice(0, 90)}${c.tekst.length > 90 ? '…' : ''}" — ${c.status === 'stemming' ? '_de Raad stemt nu_' : capsuleDatum(c.deadline)}`)
      .join('\n');
    return [
      ...homeKaartKop('⏳ VERZEGELDE TIJDCAPSULES'),
      { type: 'section', text: { type: 'mrkdwn', text: `${regels}\n\n_Verzegel er zelf een met_ \`/kroketgod voorspel [wanneer] [wat]\`` } },
    ];
  },
});

// ══════════════════════════════════════════════════════════════════════════════
// HET VERHOOR — wie zei dit?
// ══════════════════════════════════════════════════════════════════════════════
// De Kroket God diept een ECHT citaat uit Het Grote Archief op en de Raad raadt wie het zei.
// Juist geraden is +1 kroketpunt; wie ernaast zit krijgt niets (geen straf — dit is een spel
// over herinnering, niet over schuld).
//
// KOST NUL LLM-QUOTA. Alle teksten zijn templated en de inhoud komt uit het archief. Dat is de
// hele grap: het spel wordt geschreven door de leden zelf, en hoe meer er gekletst wordt, hoe
// meer munitie er is. Het is daarmee het eerste spel hier dat gratis groeit.
//
// DE SPREKER MAG NIET MEEDOEN — die weet het antwoord. Hij staat wél tussen de keuzes, anders
// zou het juiste antwoord er niet bij zitten.
//
// CITATEN ZIJN MINSTENS VERHOOR_MIN_LEEFTIJD_DAGEN OUD. Een uitspraak van gisteren herkent
// iedereen nog; pas als het even geleden is, wordt het raden. Gebruikte citaten worden
// vastgelegd zodat er nooit twee keer hetzelfde langskomt.

const VERHOOR_MIN_LEEFTIJD_DAGEN = 5;
const VERHOOR_BELONING = 1;
// Hoeveel eerder gebruikte citaten we onthouden. Ruim boven het aantal weken dat dit spel
// realistisch draait, zodat een herhaling in de praktijk niet voorkomt.
const VERHOOR_GESCHIEDENIS_MAX = 200;

const loadVerhoor = () => readJSON('verhoor.json', {});
const saveVerhoor = (data) => writeJSON('verhoor.json', data);

function bouwVerhoorBlocks(v) {
  const members = loadMembers();
  const naam = (id) => members[id]?.bijnaam || 'een verdwenen volgeling';
  const aantalGokken = Object.keys(v.antwoorden || {}).length;
  const teGaan = (v.opties || []).filter(id => id !== v.sprekerId && !(v.antwoorden || {})[id]).length;

  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: '🕯️ HET VERHOOR', emoji: true } },
    { type: 'section', text: { type: 'mrkdwn', text:
      `_Uit de archieven van de Hoge Frituurraad, opgetekend op ${archiefDatum(v.citaatTs)}:_\n\n> "${v.tekst}"\n\n*Wie sprak deze woorden?*` } },
  ];

  if (!v.onthuld) {
    // De keuzes staan in vaste (alfabetische) volgorde en niet op stand: anders verraadt de
    // plek van een naam iets over wie het waarschijnlijk was.
    const opties = [...(v.opties || [])].sort((a, b) => naam(a).localeCompare(naam(b)));
    blocks.push({ type: 'actions', elements: opties.slice(0, 5).map(id => ({
      type: 'button',
      text: { type: 'plain_text', text: naam(id).slice(0, 60), emoji: true },
      action_id: `verhoor_gok_${id}`,
      value: id,
    })) });
    blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text:
      `${aantalGokken} van de Raad heeft geantwoord${teGaan ? `, ${teGaan} nog niet` : ''} · ` +
      `wie het juist heeft krijgt *+${VERHOOR_BELONING}* · de spreker zelf mag niet meedoen · onthulling vanmiddag 16:00` }] });
    return blocks;
  }

  // Onthuld: wie zat er goed, wie zat er naast, en wie heeft er niets van gezegd.
  const goed = Object.entries(v.antwoorden || {}).filter(([, gok]) => gok === v.sprekerId).map(([id]) => id);
  const fout = Object.entries(v.antwoorden || {}).filter(([, gok]) => gok !== v.sprekerId);
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text:
    `⚜️ *Het was ${naam(v.sprekerId)}.*\n\n` +
    (goed.length ? `> ✅ Juist geraden: ${goed.map(id => `*${naam(id)}*`).join(', ')} — *+${VERHOOR_BELONING}* elk.\n` : '> _Niemand had het juist. De Raad kent zijn eigen woorden niet._\n') +
    (fout.length ? `> ❌ Ernaast: ${fout.map(([id, gok]) => `*${naam(id)}* (dacht ${naam(gok)})`).join(', ')}.\n` : '') } });
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text:
    'Het archief vergeet niets · volgende verhoor donderdag' }] });
  return blocks;
}

async function updateVerhoorBericht(client, v) {
  if (!v.berichtTs || !v.kanaal) return;
  try {
    await slackLimiter.schedule(() => client.chat.update({
      channel: v.kanaal, ts: v.berichtTs,
      text: 'Het Verhoor — wie zei dit?',
      blocks: bouwVerhoorBlocks(v),
    }));
  } catch (err) {
    console.warn('⚠️ Verhoor-bord bijwerken mislukt:', err.data?.error || err.message);
  }
}

async function startVerhoor(client) {
  const bestaand = loadVerhoor();
  // Loopt er nog een onafgeronde ronde, dan die eerst onthullen — anders zou een gemiste
  // onthulling de vorige ronde voorgoed open laten staan.
  if (bestaand.ronde && !bestaand.ronde.onthuld) {
    await onthulVerhoor(client);
  }
  const members = loadMembers();
  const spelers = Object.keys(members).filter(id => !isVerbannen(id));
  // Onder drie leden is raden zinloos: met twee opties is het een muntworp.
  if (spelers.length < 3) return null;

  const gebruikt = new Set(bestaand.gebruikt || []);
  const citaat = willekeurigCitaat({
    soort: 'lid',
    minLengte: 40,
    ouderDan: Date.now() - VERHOOR_MIN_LEEFTIJD_DAGEN * 86_400_000,
    nieuwerDan: gedeeldSinds(),
    sprekerIds: spelers,
    uitgesloten: gebruikt,
  });
  if (!citaat) {
    console.log('🕯️ Verhoor overgeslagen: geen geschikt citaat in het archief.');
    return null;
  }

  const ronde = {
    ts: Date.now(),
    citaatTs: citaat.ts,
    sprekerId: citaat.sprekerId,
    tekst: citaat.tekst,
    opties: spelers,
    antwoorden: {},
    onthuld: false,
    kanaal: process.env.SLACK_CHANNEL_ID,
    berichtTs: null,
  };
  const verstuurd = await slackLimiter.schedule(() => client.chat.postMessage({
    channel: ronde.kanaal,
    text: 'Het Verhoor — wie zei dit?',
    blocks: bouwVerhoorBlocks(ronde),
  }));
  ronde.berichtTs = verstuurd.ts;
  saveVerhoor({
    ronde,
    gebruikt: [...(bestaand.gebruikt || []), citaat.ts].slice(-VERHOOR_GESCHIEDENIS_MAX),
  });
  console.log(`🕯️ Verhoor geopend: citaat van ${members[citaat.sprekerId]?.bijnaam} uit ${archiefDatum(citaat.ts)}.`);
  return ronde;
}

// Eén gok. Geen `await` tussen lezen en schrijven, zodat twee gelijktijdige klikken elkaar niet
// kunnen overschrijven (zelfde regel als de raid- en veilingknoppen).
async function gokVerhoor(client, userId, gokId) {
  const data = loadVerhoor();
  const v = data.ronde;
  if (!v || v.onthuld) return { ok: false, tekst: '_Er loopt op dit moment geen verhoor._' };
  if (!loadMembers()[userId]) return { ok: false, tekst: '_Alleen leden van de Raad worden gehoord._' };
  if (isVerbannen(userId)) return { ok: false, tekst: '_Een balling wordt niet om zijn oordeel gevraagd._' };
  if (userId === v.sprekerId) return { ok: false, tekst: '_U heeft deze woorden zelf gesproken. Uw stem zou het verhoor bederven._' };
  if (v.antwoorden[userId]) {
    return { ok: false, tekst: `_U heeft al geantwoord: ${loadMembers()[v.antwoorden[userId]]?.bijnaam || 'onbekend'}. Een tweede kans kent het verhoor niet._` };
  }
  if (!v.opties.includes(gokId)) return { ok: false, tekst: '_Die naam staat niet op de lijst van verdachten._' };

  v.antwoorden[userId] = gokId;
  saveVerhoor({ ...data, ronde: v });
  await updateVerhoorBericht(client, v);

  // Heeft iedereen die mag antwoorden geantwoord? Dan meteen onthullen in plaats van tot 16:00
  // te wachten — er valt niets meer op te wachten.
  const magAntwoorden = v.opties.filter(id => id !== v.sprekerId && !isVerbannen(id));
  if (magAntwoorden.every(id => v.antwoorden[id])) {
    await onthulVerhoor(client);
    return { ok: true, tekst: '_Uw antwoord is opgetekend. De Raad heeft voltallig gesproken — het vonnis staat in het kanaal._' };
  }
  return { ok: true, tekst: '_Uw antwoord is opgetekend. Niemand ziet wat u koos tot de onthulling._' };
}

async function onthulVerhoor(client) {
  const data = loadVerhoor();
  const v = data.ronde;
  if (!v || v.onthuld) return null;
  v.onthuld = true;
  saveVerhoor({ ...data, ronde: v }); // eerst vastleggen: dubbele onthulling is dubbele punten
  await updateVerhoorBericht(client, v);

  const members = loadMembers();
  const goed = Object.entries(v.antwoorden || {}).filter(([, gok]) => gok === v.sprekerId).map(([id]) => id);
  for (const id of goed) {
    if (!members[id]) continue;
    await pasScoreAanMetCheck(client, id, VERHOOR_BELONING, { channelId: v.kanaal });
    await telActie(client, id, 'verhoor_juist');
    logGebeurtenis('verhoor', id, `${members[id].bijnaam} herkende de woorden van ${members[v.sprekerId]?.bijnaam || 'een oud-lid'} (+${VERHOOR_BELONING})`);
  }
  console.log(`🕯️ Verhoor onthuld: ${goed.length} van ${Object.keys(v.antwoorden || {}).length} juist.`);
  return { goed: goed.length };
}

registreerFeature({
  naam: 'verhoor',
  state: ['verhoor.json'],
  help: [{ gebruik: '/kroketgod verhoor', verwacht: 'het lopende verhoor: een echt citaat uit het archief — raad wie het zei (+1 bij juist)' }],
});

// Donderdag 11:00 openen, 16:00 onthullen. Eigen expressies, dus dashboard-"overslaan" werkt
// per onderdeel; de onthulling staat bewust NIET in CRON_LABELS — die overslaan zou een ronde
// voorgoed open laten staan, en dat is geen keuze die iemand bewust wil maken.
planCron('0 11 * * 4', async () => {
  try { await startVerhoor(app.client); }
  catch (err) { console.error('⚠️ Verhoor openen mislukt:', err.message); }
}, { timezone: 'Europe/Amsterdam' });

planCron('0 16 * * 4', async () => {
  try { await onthulVerhoor(app.client); }
  catch (err) { console.error('⚠️ Verhoor onthullen mislukt:', err.message); }
}, { timezone: 'Europe/Amsterdam' });

// ── De Tijdcapsule: dagelijks 10:10 ontzegelen en beslechten ──────────────────
// Eén cron voor beide fasen; alles is uit tijdstempels afgeleid, dus een gemiste dag haalt zich
// de volgende dag in. Geen CRON_LABELS-entry: op de meeste dagen post dit niets, en overslaan
// zou een capsule voor onbepaalde tijd dicht houden.
planCron('10 10 * * *', async () => {
  try { await verwerkCapsuleKlok(app.client); }
  catch (err) { console.error('⚠️ Capsuleklok mislukt:', err.message); }
}, { timezone: 'Europe/Amsterdam' });

app.action(/^verhoor_gok_/, async ({ ack, body, client }) => {
  await ack();
  try {
    const gokId = body.actions?.[0]?.value;
    if (!gokId) return;
    const uitkomst = await gokVerhoor(client, body.user.id, gokId);
    await meldKnopUitkomst(client, body, uitkomst.tekst);
  } catch (err) { console.error('Fout bij verhoorknop:', err); }
});

// Dagelijks om 03:15 — na de nachtelijke herstart (03:00) zodat data stabiel is
planCron('15 3 * * *', maakBackup, { timezone: 'Europe/Amsterdam' });

// ── De Voorraadkelder: nachtelijk vooruit genereren ───────────────────────────
// 03:40, ná de backup (03:15) en ná de nachtelijke herstart (03:00): de kelder is dan al meegegaan in de
// backup van vandaag, en er is geen herstart die het vullen halverwege afbreekt.
//
// Bewust dezelfde Amsterdamse kalenderdag als de posts die eruit komen (07:30–15:00), zodat de
// stemming van de dag klopt — die is per dag geseed, zie getDagelijkseStemming.
//
// WAT HIER WEL IN MAG: uitsluitend inhoud die naar geen enkele levende stand verwijst. Zie de
// kop van lib/voorraad.js; een post die een score, naam of vijand-HP noemt hoort hier nooit.
registreerFeature({
  naam: 'voorraadkelder',
  state: [VOORRAAD_BESTAND],
});

// Doelvoorraad per soort. Iets ruimer dan het aantal posts per dag (feitje 1×/dag op werkdagen,
// spontaan 2× op di/do met 50% kans), zodat een mislukte nacht niet direct tot stilte leidt.
const VOORRAAD_DOELEN = [
  { soort: 'feitje',   doel: 2, maker: maakKroketFeitje },
  { soort: 'spontaan', doel: 2, maker: maakAlgemeneSpontanePost },
];

planCron('40 3 * * *', async () => {
  try {
    const opgeruimd = ruimVoorraadOp();
    const uitkomsten = [];
    for (const { soort, doel, maker } of VOORRAAD_DOELEN) {
      // Serieel, niet parallel: parallelle aanroepen zouden elkaars rate-limits opzoeken en de
      // per-key cooldowns in lib/llm.js tegen elkaar laten werken. Er wacht niemand, dus tijd
      // is hier het goedkoopste dat we hebben.
      uitkomsten.push(await vulVoorraad(soort, doel, maker));
    }
    const samenvatting = uitkomsten
      .map(u => `${u.soort} +${u.gemaakt}${u.mislukt ? ` (${u.mislukt} mislukt)` : ''}${u.dubbel ? ` (${u.dubbel} dubbel)` : ''}`)
      .join(', ');
    console.log(`🏚️ Voorraadkelder bijgevuld: ${samenvatting}${opgeruimd ? ` · ${opgeruimd} verlopen opgeruimd` : ''}.`);
  } catch (err) {
    console.error('⚠️ Voorraadkelder vullen mislukt:', err.message);
  }
}, { timezone: 'Europe/Amsterdam' });

// ── Quota-monitor ────────────────────────────────────────────────────────────
// Logt elk uur hoe vol de providers zitten, zodat je in de containerlogs ziet wanneer limieten
// vollopen/resetten i.p.v. te gokken. Groq via een minimale probe (eigen dag-quota is enorm, dit
// is verwaarloosbaar); Gemini via de cooldown-state (verbruikt zelf geen quota).
let laatsteGroqQuota = null; // laatste Groq rate-limit-snapshot (voor het dashboard)
let laatsteStatSnapshot = 0; // throttle voor de dagelijkse statistiek-momentopname
async function logQuotaStatus() {
  try {
    if (process.env.GROQ_API_KEY) {
      const r = await fetch('https://api.groq.com/openai/v1/chat/completions', {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${process.env.GROQ_API_KEY}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: GROQ_SLIM, messages: [{ role: 'user', content: 'hi' }], max_tokens: 1 }),
        timeout: 10000,
      });
      const h = r.headers;
      laatsteGroqQuota = {
        ts: Date.now(),
        reqRemaining: h.get('x-ratelimit-remaining-requests'), reqLimit: h.get('x-ratelimit-limit-requests'), reqReset: h.get('x-ratelimit-reset-requests'),
        tokRemaining: h.get('x-ratelimit-remaining-tokens'), tokLimit: h.get('x-ratelimit-limit-tokens'), tokReset: h.get('x-ratelimit-reset-tokens'),
      };
      console.log(`📊 Groq ${GROQ_SLIM} — requests ${h.get('x-ratelimit-remaining-requests')}/${h.get('x-ratelimit-limit-requests')} (reset ${h.get('x-ratelimit-reset-requests')}), tokens ${h.get('x-ratelimit-remaining-tokens')}/${h.get('x-ratelimit-limit-tokens')} per min (reset ${h.get('x-ratelimit-reset-tokens')})`);
    }
  } catch (e) { console.warn('📊 Groq quota-check faalde:', e.message); }

  // Gemini: hoeveel keys staan momenteel in cooldown of op de bank? Geen quota-verbruik.
  const keys = geminiKeys();
  if (keys.length) {
    const nu = Date.now();
    const tot = keys.map(k => geminiSleutelVrijOp(k, nu));
    const vrij = tot.filter(t => !t).length;
    const eerstvrij = vrij > 0 ? 0 : Math.round((Math.min(...tot) - nu) / 1000);
    console.log(`📊 Gemini — ${vrij}/${keys.length} keys vrij${vrij === 0 ? `, eerstvolgende over ~${eerstvrij}s` : ''}`);
  }
  // De bank: wat staat er langdurig uit de keten, en waarom.
  const bank = bankLijst();
  if (bank.length) {
    console.log(`📊 Op de bank — ${bank.map(r => `${r.label} (${r.status ?? '?'}${r.reden ? `, ${r.reden}` : ''}) nog ${Math.round(r.restMs / 60_000)} min`).join(' · ')}`);
  }
}
// Elk uur, niet elk kwartier: de Groq-meting is een echt verzoek aan gpt-oss-120b, en 96 per dag
// was bijna een tiende van zijn gratis daglimiet aan verzoeken — juist het model waar de keten op
// leunt als Gemini op is. Het dashboard ververst zelf als zijn meting ouder is dan 5 minuten.
planCron('7 * * * *', logQuotaStatus, { timezone: 'Europe/Amsterdam' });
// Eén keer kort na opstart, zodat je meteen een meting hebt (en bij elke herstart).
setTimeout(() => logQuotaStatus().catch(() => {}), 15000);

// ── Dashboard (poort 3001) ───────────────────────────────────────────────────
// Verzamelt alle dashboard-data: bot-status, LLM/provider-status, ranglijst, bans, activiteit.
async function bouwDashboardData() {
  // Verse Groq-meting als de snapshot ouder is dan 5 min (anders cache gebruiken).
  if (!laatsteGroqQuota || Date.now() - laatsteGroqQuota.ts > 5 * 60_000) {
    try { await logQuotaStatus(); } catch (_) {}
  }
  const nu = Date.now();
  const members = loadMembers();
  const scores = loadScores();
  const roem = loadRoem();
  const verbanning = loadVerbanning();
  const vergrijpen = loadVergrijpen();
  const kennis = loadKennisbank();
  const achievements = loadAchievements();
  const kvdd = loadKroketVanDeDag();
  const week = loadWeekgebeurtenissen();
  const naam = (id) => members[id]?.bijnaam || id;

  const ranglijst = Object.entries(scores)
    .map(([id, score]) => ({ id, naam: naam(id), score, roem: roem[id] || 0 })).sort((a, b) => b.score - a.score);
  const bans = Object.entries(verbanning)
    .filter(([, v]) => new Date(v.tot).getTime() > nu)
    .map(([id, v]) => ({ id, naam: naam(id), tot: v.tot, reden: v.reden || '' }))
    .sort((a, b) => new Date(a.tot) - new Date(b.tot));
  const actieveVergrijpen = Object.entries(vergrijpen)
    .map(([id, lijst]) => ({ naam: naam(id), aantal: (lijst || []).filter(x => nu - x.ts < VERGRIJP_VENSTER_MS).length }))
    .filter(x => x.aantal > 0).sort((a, b) => b.aantal - a.aantal);

  // Uit de ketendefinitie zelf, niet uit een eigen lijst: die noemde "Groq 70B" en "Groq 8B-instant"
  // terwijl de keten allang op gpt-oss-120b/20b draaide. Cooldown-keys zijn `provider:model`
  // (Groq-limieten zijn per model), dus elke schakel heeft zijn eigen cooldown en bankregel.
  const keys = geminiKeys();
  const geminiKeysStatus = keys.map((k, i) => {
    const t = geminiSleutelVrijOp(k, nu);
    return { nr: i + 1, vrij: !t, resetOver: t ? Math.round((t - nu) / 1000) : 0 };
  });
  const providers = ketenDefinitie().map(m => {
    const t = providerCooldownTot.get(m.cooldownKey) || 0;
    const bank = bankStatus(m.cooldownKey, nu);
    return {
      naam: m.label, provider: m.provider, tier: m.tier, actief: m.beschikbaar,
      cooldown: t > nu ? Math.round((t - nu) / 1000) : 0,
      bank: bank ? { status: bank.status, reden: bank.reden, trap: Number.isInteger(bank.trap) ? bank.trap + 1 : null, restSec: Math.round((bank.tot - nu) / 1000) } : null,
    };
  });
  // Alles wat op de bank staat, ook Gemini-sleutels met hun dagquotum op en het beeldquotum.
  const bank = bankLijst(nu).map(r => ({ label: r.label, status: r.status, reden: r.reden, trap: r.trap, restSec: Math.round(r.restMs / 1000) }));

  // Aggregaties voor de grafieken op het dashboard (uit de gebeurtenissen van deze week).
  const DAG_LABELS = ['ma', 'di', 'wo', 'do', 'vr', 'za', 'zo'];
  const perDag = [0, 0, 0, 0, 0, 0, 0];
  const perType = {};
  for (const e of (week.events || [])) {
    const dow = amsWeekdag(new Date(e.ts)) - 1; // ma = 0 … zo = 6, in Amsterdamse tijd (het proces draait op UTC)
    perDag[dow]++;
    perType[e.type] = (perType[e.type] || 0) + 1;
  }
  const grafieken = {
    activiteitPerDag: DAG_LABELS.map((dag, i) => ({ dag, aantal: perDag[i] })),
    activiteitPerType: Object.entries(perType)
      .map(([type, aantal]) => ({ type, aantal })).sort((a, b) => b.aantal - a.aantal),
  };

  // Langlopende geschiedenis: dagelijkse momentopname wegschrijven (gethrottled op 10 min)
  // en de laatste 30 dagen teruggeven voor de trendgrafieken.
  const totaalScore = Object.values(scores).reduce((a, b) => a + (b || 0), 0);
  const achievementsTotaal = Object.values(achievements)
    .reduce((n, a) => n + (Array.isArray(a) ? a.length : 0), 0);
  if (nu - laatsteStatSnapshot > 10 * 60_000) {
    snapshotStatHistorieVandaag({
      leden: Object.keys(members).length,
      totaalScore,
      bans: bans.length,
      kennisbank: Array.isArray(kennis) ? kennis.length : 0,
      achievements: achievementsTotaal,
    });
    laatsteStatSnapshot = nu;
  }
  const gesch = loadStatHistorie();
  grafieken.geschiedenis = Object.keys(gesch.dagen || {}).sort().slice(-30).map(d => {
    const x = gesch.dagen[d];
    return {
      datum: d,
      events: x.events || 0,
      leden: x.leden ?? null,
      totaalScore: x.totaalScore ?? null,
    };
  });

  // Eerstvolgende ingeplande bericht: alle terugkerende botposts + eigen geplande
  // verkondigingen samen; alleen het eerstvolgende item wordt aan het dashboard getoond.
  const ingeplandPool = [];
  for (const m of geplandeCronMeta) {
    const ts = volgendeCronTijd(m.toonExpr, nu);
    if (ts) ingeplandPool.push({ soort: 'terugkerend', key: m.key, label: m.label, ts });
  }
  for (const b of (loadGeplandeBerichten().berichten || [])) {
    if (b.status === 'wacht') {
      ingeplandPool.push({ soort: 'eenmalig', id: b.id, label: b.tekst, kanaal: b.kanaal, ts: b.ts });
    }
  }
  ingeplandPool.sort((a, b) => a.ts - b.ts);
  const ingepland = ingeplandPool.slice(0, 5); // de eerstvolgende vijf

  // Aflatenhandel: actieve power-ups/vloeken, aankoophistorie en totalen per koper.
  // NB: dit is de admin-weergave achter het token — hier is de vloek-legger wél zichtbaar.
  const powerupsData = loadPowerups();
  const winkelActief = [];
  for (const [id, lijst] of Object.entries(powerupsData)) {
    for (const p of (lijst || [])) {
      if (p.tot <= nu) continue;
      winkelActief.push({
        userId: id, naam: naam(id), item: p.item,
        itemNaam: WINKEL_ITEMS[p.item]?.naam || p.item,
        icoon: WINKEL_ITEMS[p.item]?.icoon || '•',
        tot: p.tot,
        door: p.item === 'vloek' ? (p.door === 'dashboard' ? 'dashboard' : (p.door ? naam(p.door) : 'onbekend')) : null,
      });
    }
  }
  winkelActief.sort((a, b) => a.tot - b.tot);
  const winkelHistItems = loadWinkelHistorie().items || [];
  const winkelTotalen = {};
  for (const h of winkelHistItems) {
    const koper = h.koperId ? naam(h.koperId) : 'dashboard';
    const t = (winkelTotalen[koper] ||= { koper, perItem: {}, aantal: 0, besteed: 0 });
    t.perItem[h.item] = (t.perItem[h.item] || 0) + 1;
    t.aantal++;
    t.besteed += h.prijs || 0;
  }
  const winkel = {
    leden: Object.entries(members).map(([id, m]) => ({ id, naam: m.bijnaam || id })),
    catalogus: Object.entries(WINKEL_ITEMS).map(([key, w]) => ({ key, naam: w.naam, icoon: w.icoon, prijs: w.prijs })),
    actief: winkelActief,
    historie: winkelHistItems.slice(-20).reverse().map(h => ({
      ts: h.ts,
      koper: h.koperId ? naam(h.koperId) : 'dashboard',
      item: h.item,
      itemNaam: WINKEL_ITEMS[h.item]?.naam || h.item,
      icoon: WINKEL_ITEMS[h.item]?.icoon || '•',
      doel: h.doelId ? naam(h.doelId) : null,
      prijs: h.prijs || 0,
      bron: h.bron || 'slack',
    })),
    totalen: Object.values(winkelTotalen).sort((a, b) => b.aantal - a.aantal),
  };

  // Spelstatus voor het Spel-tabblad: troon, gouden kroket, kroket-gok, quiz, bingo,
  // allianties, streaks en heldentitels. Dit is de admin-weergave — de geplande tijd van
  // de Gouden Kroket en de gedane gokken zijn hier wél zichtbaar.
  const troonData = readJSON('troon.json', { koningId: null, sinds: null });
  const gkData = loadGoudenKroket();
  const gokData = readJSON('kroketgok.json', {});
  const quizData = loadQuiz();
  const bingoData = readJSON('bingo.json', {});
  const streaksData = loadStreaks();
  const heldentitelsData = loadHeldentitels();
  // Zelfde vorm { a, b } als vroeger, zodat dashboard.html ongewijzigd blijft: bij een verbond van
  // drie staan de andere twee samen in b.
  const alliantieParen = alleVerbonden().map(g => ({ a: naam(g[0]), b: g.slice(1).map(naam).join(' & ') }));
  const spel = {
    casino: casinoDashboardData(naam),
    troon: troonData.koningId && members[troonData.koningId]
      ? { koning: naam(troonData.koningId), sinds: troonData.sinds, score: scores[troonData.koningId] || 0 }
      : null,
    goudenKroket: {
      geplandVoor: gkData.geplandVoor || null,
      geplaatst: !!gkData.geplaatst,
      gepakt: !!gkData.gepakt,
      winnaar: gkData.winnaar ? naam(gkData.winnaar) : null,
    },
    kroketGok: {
      kroket: kvdd?.naam || null,
      actief: !!(kvdd?.ts && kvdd.datum === new Date().toISOString().slice(0, 10)),
      gokken: (gokData.ts && kvdd?.ts && gokData.ts === kvdd.ts)
        ? Object.entries(gokData.gokken || {}).map(([id, keuze]) => ({ naam: naam(id), keuze }))
        : [],
    },
    quiz: quizData.ts
      ? { vraag: quizData.vraag, deadline: quizData.deadline, afgerond: !!quizData.afgerond }
      : null,
    bingo: Array.isArray(bingoData.opdrachten)
      ? {
          weekStart: bingoData.weekStart,
          opdrachten: bingoData.opdrachten.map((tekst, i) => ({
            nr: i + 1,
            tekst,
            claims: Object.entries(bingoData.claims || {})
              .filter(([, idx]) => Array.isArray(idx) && idx.includes(i))
              .map(([id]) => naam(id)),
          })),
        }
      : null,
    allianties: alliantieParen,
    streaks: Object.entries(streaksData)
      .map(([id, s]) => ({ naam: naam(id), huidig: s?.huidig || 0, record: s?.record || 0 }))
      .filter(s => s.huidig > 0 || s.record > 0)
      .sort((a, b) => b.huidig - a.huidig),
    heldentitels: Object.entries(heldentitelsData)
      .map(([id, aantal]) => ({ naam: naam(id), aantal }))
      .sort((a, b) => b.aantal - a.aantal),
  };

  const stemming = getDagelijkseStemming();
  return {
    ingepland,
    winkel,
    spel,
    instellingen: loadInstellingen(),
    // Geen scheveKansen-veld meer: de eigenaar wil de kansmechaniek nergens vermeld hebben, dus hij
    // staat ook niet in deze API. Zie de noot bij getGeluk — dat is een bewuste keuze, geen omissie.
    stemmingOpties: STEMMINGEN.map(s => s.naam),
    providerOpties: [...new Set(providers.map(p => p.provider))],
    nu,
    bot: {
      // 'slack-onbereikbaar' is een echte toestand: het proces leeft, maar de bot is stil in
      // Slack. Zonder dit onderscheid leek een DNS-storing gewoon "online".
      status: !isReady ? 'opstarten' : (slackGezond() ? 'online' : 'slack-onbereikbaar'),
      slackLaatstOkSec: Math.round((Date.now() - slackLaatstOk) / 1000),
      slackMisluktePogingen: slackFouten,
      slackLaatsteFout: slackLaatsteFout,
      uptimeSec: Math.round(process.uptime()),
      memMb: Math.round(process.memoryUsage().rss / 1048576),
      stemming: stemming?.naam || '—',
      vrijdagSec: secondenTotVrijdagMiddag(),
      weekend: isNaHeiligMoment(),
    },
    llm: { geminiKeys: geminiKeysStatus, providers, bank, groq: laatsteGroqQuota },
    stats: {
      leden: Object.keys(members).length,
      ranglijst,
      bans,
      vergrijpen: actieveVergrijpen,
      kennisbank: Array.isArray(kennis) ? kennis.length : 0,
      achievements: achievementsTotaal,
      kroketVanDeDag: kvdd?.naam ? { naam: kvdd.naam, datum: kvdd.datum } : null,
      archief: archiefOmvang(),
      voorraad: voorraadStand(),
    },
    grafieken,
    activiteit: (week.events || []).slice(-30).reverse()
      .map(e => ({ ts: e.ts, type: e.type, naam: e.userId ? naam(e.userId) : null, actorNaam: e.actorId ? naam(e.actorId) : null, beschrijving: e.beschrijving })),
    llmstats: readJSON('llmstats.json', { dagen: {} }),
    frituurlog: (readJSON('frituurlog.json', { items: [] }).items || []).slice().reverse(),
    auditlog: (readJSON('auditlog.json', { items: [] }).items || []).slice(-20).reverse(),
    personas: (() => {
      const vandaag = new Set(gastenVandaag().map(g => g.id));
      return Object.entries(loadPersonas()).map(([id, p]) => ({ id, ...p, vandaag: vandaag.has(id) }));
    })(),
    huisonderwerpen: {
      actief: actieveHuisonderwerpen(),
      voorstellen: (loadVoorstellen().voorstellen || []).map(v => ({ ...v, naam: loadMembers()[v.door]?.bijnaam || v.door })),
    },
  };
}

// Aflatenhandel-beheer vanuit het dashboard: geef of verwijder een power-up bij een lid,
// zonder kroketpunten te rekenen. Optioneel met dezelfde publieke aankondiging als bij een
// echte aankoop — bij een vloek blijft de afzender ook dan verborgen voor het kanaal.
// Eerbewijs vanaf het dashboard. Alle toetsen die in Slack gelden, gelden hier ook — de enige
// reden dat dit een eigen functie is, is dat het dashboard geen Slack-client meegekregen heeft
// en zijn fouten als exceptie wil (die worden statusregels in de browser).
async function voerDashboardEer(geverId, ontvangerId, reden) {
  const members = loadMembers();
  if (!geverId || !members[geverId]) throw new Error('Onbekende gever');
  if (!ontvangerId || !members[ontvangerId]) throw new Error('Onbekende ontvanger');
  if (geverId === ontvangerId) throw new Error('Zelflof: kies twee verschillende leden');
  if (isVerbannen(geverId)) throw new Error(`${members[geverId].bijnaam} is verbannen en deelt geen eer uit`);
  const probleem = redenProbleem(reden);
  if (probleem === 'leeg') throw new Error('Reden is verplicht — beschrijf de daad');
  if (probleem === 'kort') throw new Error(`Reden te kort (minimaal ${EER_REDEN_MIN} tekens)`);
  // Daglimiet net als bij elke andere ingang: de gever, niet de beheerder, betaalt het eerbewijs.
  const besteed = telEerVandaag(geverId);
  if (besteed >= eerLimiet(geverId)) {
    throw new Error(`${members[geverId].bijnaam} heeft zijn dagelijkse eerlimiet (${eerLimiet(geverId)}) al bereikt`);
  }
  const uitkomst = await voerEer(app.client, geverId, [ontvangerId], reden, KANAAL(), { bron: 'dashboard' });
  if (!uitkomst.ok) throw new Error(uitkomst.tekst.replace(/^_|_$/g, ''));
  const punten = uitkomst.punten[ontvangerId];
  return `${members[geverId].bijnaam} eerde ${members[ontvangerId].bijnaam}: ${punten === 0 ? 'niets' : `+${punten}`} ` +
    `(${uitkomst.klasse}${uitkomst.herhaald ? ', herhaalde reden' : ''})${uitkomst.terugslag ? ` · verbondstrouw +${uitkomst.terugslag}` : ''}`;
}

// Huisonderwerp-beheer vanuit het dashboard. Goedkeuren laat het woord meewegen bij elk
// eerbewijs, dus het gaat langs dezelfde toets als de voordracht zelf — een woord dat intussen
// te algemeen is geworden (omdat er al iets soortgelijks goedgekeurd is) wordt hier alsnog
// geweigerd in plaats van stilletjes toegelaten.
async function voerHuisonderwerpBeheer(woord, actie) {
  const data = loadVoorstellen();
  const lijst = data.voorstellen || [];
  const i = lijst.findIndex(v => v && v.woord === woord);
  if (i < 0) throw new Error('Onbekend voorstel');
  const v = lijst[i];
  const members = loadMembers();
  const naam = members[v.door]?.bijnaam || v.door;
  if (actie === 'verwijderen') {
    data.voorstellen = lijst.filter((_, j) => j !== i);
    saveVoorstellen(data);
    return `Huisonderwerp "${woord}" van ${naam} verwijderd.`;
  }
  if (actie === 'afwijzen') {
    data.voorstellen = lijst.map((x, j) => (j === i ? { ...x, status: 'afgewezen' } : x));
    saveVoorstellen(data);
    return `Huisonderwerp "${woord}" van ${naam} afgewezen.`;
  }
  if (actie !== 'goedkeuren') throw new Error('Onbekende actie (goedkeuren/afwijzen/verwijderen)');
  const probleem = onderwerpProbleem(woord, actieveHuisonderwerpen());
  if (probleem) throw new Error(`Kan niet goedkeuren — ${ONDERWERP_UITLEG[probleem] || probleem}`);
  data.voorstellen = lijst.map((x, j) => (j === i ? { ...x, status: 'goedgekeurd', goedgekeurdTs: Date.now() } : x));
  saveVoorstellen(data);
  // Eén regel in het kanaal, want dit verandert de spelregels voor iedereen. Niet meer dan een
  // regel: de Raad kondigt al genoeg aan.
  try {
    await postToChannel(app.client, KANAAL(),
      `📖 De Raad neemt *${woord}* op in het huisboek, op voordracht van <@${v.door}>. Een eerbewijs dat dit raakt weegt voortaan een klasse zwaarder.`);
  } catch (_) { /* het dashboard mag niet struikelen over een stille Slack */ }
  return `Huisonderwerp "${woord}" van ${naam} goedgekeurd.`;
}

async function voerWinkelBeheer(actie, userId, item, aankondig) {
  const members = loadMembers();
  if (!userId || !members[userId]) throw new Error('Onbekend lid');
  const w = WINKEL_ITEMS[item];
  if (!w) throw new Error('Onbekend winkel-item');
  const naam = members[userId].bijnaam;

  if (actie === 'verwijder') {
    if (!heeftPowerup(userId, item)) throw new Error(`${w.naam} is niet actief op ${naam}`);
    verwijderPowerup(userId, item);
    logGebeurtenis('winkel', userId, `${w.naam} op ${naam} verwijderd via het dashboard`);
    return `${w.naam} verwijderd bij ${naam}`;
  }
  if (actie !== 'geef') throw new Error('Onbekende actie');

  if (heeftPowerup(userId, item)) throw new Error(`${w.naam} is al actief op ${naam}`);
  geefPowerup(userId, item, item === 'vloek' ? { door: 'dashboard' } : {});
  registreerWinkelAankoop(null, item, 0, userId, 'dashboard');
  logGebeurtenis('winkel', userId, `${w.naam} toegekend aan ${naam} via het dashboard`);

  if (aankondig) {
    const teksten = {
      zegen: `> De Hoge Frituurraad schenkt *${naam}* de *Zegen van de Paneerlaag* — 24 uur lang ketst elke puntenstraf af op de heilige korst.`,
      dubbele_eer: `> De Hoge Frituurraad schenkt *${naam}* de zegen van *Dubbele Eer* — 24 uur lang telt elke ontvangen eer dubbel.`,
      gouden_korst: `> De Hoge Frituurraad bekleedt *${naam}* met de *Gouden Korst* — 24 uur gouden status. Spreek voortaan van de Gezalfde.`,
      vloek: `> In de schaduwen is een *Vloek der Slappe Korst* gelegd op *${naam}*. Diens eerstvolgende puntenwinst kan verbranden in het vet.`,
    };
    const kop = item === 'vloek' ? '😈 *EEN VLOEK IS GELEGD* 😈' : `${w.icoon} *EEN GESCHENK VAN DE RAAD* ${w.icoon}`;
    await postToChannel(app.client, process.env.SLACK_CHANNEL_ID, `${kop}\n\n${teksten[item]}\n\n— De Hoge Frituurraad`);
  }
  return `${w.naam} gegeven aan ${naam}${aankondig ? ' (aangekondigd)' : ' (stil)'}`;
}

// Voert een actieknop van het dashboard uit.
// Herschrijft een gewone boodschap in de tone of voice van de Kroket God (1 LLM-call, geen post).
async function vertaalNaarKroketGod(tekst) {
  const schoon = (tekst || '').trim();
  if (!schoon) throw new Error('Lege boodschap');
  const prompt = `Een boodschap moet worden verkondigd aan het genootschap. Herschrijf de volgende tekst ` +
    `volledig in jouw eigen stijl en tone of voice — behoud de kern en betekenis, maar maak er een ` +
    `dramatische, gezaghebbende Kroket God-verkondiging van. Tekst: "${schoon}". Geen inleidingszin.`;
  return schoonOutput(await kroketResponse(prompt, 450, false));
}

// Plaatst een (al herschreven) tekst namens de Kroket God in het gekozen kanaal.
async function plaatsVerkondiging(tekst, kanaalKeuze) {
  const schoon = (tekst || '').trim();
  if (!schoon) throw new Error('Lege boodschap');
  const kanaal = kanaalKeuze === 'test'
    ? ([...TEST_KANAAL_IDS][0] || process.env.SLACK_CHANNEL_ID)
    : process.env.SLACK_CHANNEL_ID;
  await postToChannel(app.client, kanaal, schoon);
  return kanaalKeuze === 'test' ? 'Verkondigd in het testkanaal.' : 'Verkondigd in het hoofdkanaal.';
}

// Licht een nieuwe functie uit (lib/nieuwtjes.js): een decreet van de Kroket God, daaronder vast
// hoe het werkt en wat het kost, en knoppen om meteen te beginnen. Beheercommando `uitlichten`.
// Geeft true terug als het decreet van de keten kwam, false bij het vaste vangnet.
async function lichtFunctieUit(client, functie, kanaal) {
  // fallback: null — lukt het decreet niet, dan het vaste vangnet van de functie in plaats van
  // een losse Kroket God-spreuk die niets met de functie te maken heeft.
  const berichten = [
    { role: 'system', content: buildSystemPrompt() },
    { role: 'user', content: uitlichtPrompt(functie) },
  ];
  const decreet = await _draaiModellen(berichten, 400, 'slim', { fallback: null }).catch(() => null);
  const { tekst, knoppen } = bouwUitlichting(functie, decreet);
  await postToChannel(client, kanaal, tekst, { knoppen });
  return !!decreet;
}

// Plant een (al in tone-of-voice geschreven) verkondiging in voor een toekomstig tijdstip.
function planVerkondiging(tekst, kanaalKeuze, wanneerTs) {
  const schoon = (tekst || '').trim();
  if (!schoon) throw new Error('Lege boodschap');
  const ts = Number(wanneerTs);
  if (!ts || Number.isNaN(ts)) throw new Error('Ongeldig tijdstip');
  if (ts < Date.now() - 60_000) throw new Error('Kies een tijdstip in de toekomst');
  const data = loadGeplandeBerichten();
  const id = 'b' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  data.berichten.push({
    id, ts, tekst: schoon, kanaal: kanaalKeuze === 'test' ? 'test' : 'hoofd',
    status: 'wacht', aangemaakt: Date.now(),
  });
  saveGeplandeBerichten(data);
  return id;
}

// Verwerkt elke minuut de openstaande geplande berichten die op tijd zijn.
async function verwerkGeplandeBerichten() {
  const nu = Date.now();
  // EERST claimen, dan pas plaatsen. Deze taak draait elke minuut, en plaatsVerkondiging is een
  // LLM-call plus een Slack-post die makkelijk langer dan een minuut duurt. Met de status-write ná
  // die await zag de volgende minuutslag hetzelfde bericht nog op 'wacht' staan en plaatste het
  // opnieuw; en werd er tussentijds een nieuw bericht ingepland, dan overschreef deze write dat
  // (de `data` van vóór de await). Claimen is read-en-write zonder await ertussen, dus atomair.
  const claim = loadGeplandeBerichten();
  // Een claim die een herstart niet overleefde staat nog op 'bezig' en zou daar voor altijd blijven
  // staan. Na vijf minuten is er geen post meer onderweg, dus dan mag hij het opnieuw proberen —
  // dezelfde inhaalgedachte als bij de andere taken: de staat volgt uit tijdstempels.
  for (const b of claim.berichten) {
    if (b.status === 'bezig' && nu - (b.geclaimdTs || 0) > 5 * 60_000) b.status = 'wacht';
  }
  const teDoen = claim.berichten.filter(b => b.status === 'wacht' && b.ts <= nu);
  for (const b of teDoen) { b.status = 'bezig'; b.geclaimdTs = nu; }
  saveGeplandeBerichten(claim);
  for (const geclaimd of teDoen) {
    let status, extra;
    try { await plaatsVerkondiging(geclaimd.tekst, geclaimd.kanaal); status = 'verzonden'; }
    catch (e) { status = 'mislukt'; extra = String(e.message || e); }
    // Vers inlezen: tijdens de post kan er een nieuw bericht bij zijn gekomen.
    const na = loadGeplandeBerichten();
    const rij = na.berichten.find(x => x.id === geclaimd.id);
    if (rij) { rij.status = status; rij.verzondenTs = Date.now(); if (extra) rij.fout = extra; }
    saveGeplandeBerichten(na);
  }
  const data = loadGeplandeBerichten();
  let gewijzigd = false;
  // Oude afgehandelde berichten opruimen (ouder dan 7 dagen).
  const voor = data.berichten.length;
  data.berichten = data.berichten.filter(b => b.status === 'wacht' || b.status === 'bezig' || (b.verzondenTs || b.ts) > nu - 7 * 86_400_000);
  if (gewijzigd || data.berichten.length !== voor) saveGeplandeBerichten(data);
}
planCron('* * * * *', verwerkGeplandeBerichten, { timezone: 'Europe/Amsterdam' });

// Voert een dashboard-"overslaan" uit: terugkerende post (1× overslaan) of eenmalig bericht (annuleren).
async function voerOverslaan(soort, { key, ts, id }) {
  if (soort === 'terugkerend') {
    if (!key || !ts) throw new Error('Ongeldige overslaan-opdracht');
    markeerOverslaan(key, Number(ts));
    return 'Eerstvolgende keer wordt overgeslagen.';
  }
  if (soort === 'eenmalig') {
    const data = loadGeplandeBerichten();
    const b = data.berichten.find(x => x.id === id);
    if (!b || b.status !== 'wacht') throw new Error('Gepland bericht niet gevonden');
    b.status = 'overgeslagen';
    saveGeplandeBerichten(data);
    return 'Gepland bericht geannuleerd.';
  }
  throw new Error('Onbekend type');
}

async function voerDashboardActie(actie) {
  switch (actie) {
    case 'resetCooldowns':
      geminiKeyCooldownTot.clear(); providerCooldownTot.clear(); wisBank();
      return 'Cooldowns en bank gewist.';
    case 'ververseQuota':
      await logQuotaStatus();
      return 'Quota ververst.';
    case 'kroketVanDeDag':
      await voerKroketVanDeDagUit(app.client);
      return 'Kroket van de dag gepost.';
    case 'quizStarten':
      await genereerEnPostQuiz(app.client);
      return 'Quiz gestart.';
    case 'quizOnthul':
      await onthulQuiz(app.client);
      return 'Quiz onthuld.';
    // V2-testacties: raid/veiling nu laten beginnen i.p.v. wachten op dinsdag/vrijdag.
    // Korte looptijd (4 uur) zodat een testronde niet dagen blijft hangen.
    case 'bamischijfSpawn':
      return await spawnWeekvijand(4);
    case 'bamischijfOntsnap':
      await beslechtBamischijfOntsnapping(app.client);
      return 'Bamischijf-ontsnapping afgehandeld.';
    case 'weekvijandBeurt':
      return (await weekvijandBeurt(app.client)) || 'Geen beurt: geen actieve vijand, al gedaan vandaag, of niets te doen.';
    case 'veilingOpen':
      return await openGroteVeiling(4);
    case 'beursDecreet':
      return await verkondigBeursDecreet(app.client);
    case 'veilingHamer':
      return await laatVeilingHamerVallen();
    // Seizoen-testacties. `seizoenSync` doet wat de maandag-cron doet (fase aankondigen, of een
    // uit de tijd gelopen seizoen beslechten); de twee forceer-acties springen naar de finale.
    case 'seizoenSync': {
      const s = await zorgVoorSeizoen(app.client);
      return s ? `Seizoen ${s.nummer} (${s.dreiging.naam}): week ${s.fase}/${SEIZOEN_WEKEN}, ${s.maxHp - s.hp}/${s.maxHp} teruggedrongen.` : 'Geen seizoen.';
    }
    case 'seizoenGeveld':
      await beslechtSeizoen(app.client, 'gewonnen');
      return 'Seizoen beslecht als overwinning; nieuw seizoen gestart.';
    case 'seizoenVerloren':
      await beslechtSeizoen(app.client, 'verloren');
      return 'Seizoen beslecht als nederlaag; nieuw seizoen gestart.';
    // Ambten en de openbaring: uitproberen zonder op maandag 09:10 te wachten.
    case 'ambtswissel': {
      const st = await zorgVoorAmbten(app.client, { stil: false });
      const bezet = AMBT_KEYS.filter(k => st?.ambten?.[k]?.houderId).length;
      return `Ambtswissel uitgevoerd: ${bezet}/${AMBT_KEYS.length} ambten bezet.`;
    }
    case 'ambtsvacatures': {
      const st = await zorgVoorAmbtsVacatures(app.client);
      const vac = st ? AMBT_KEYS.filter(k => !st.ambten[k]?.houderId).length : 0;
      return `Vacaturecontrole klaar; ${vac} ambt(en) vacant.`;
    }
    case 'zegelverval':
      await laatZegelsVervallen(app.client);
      return 'Zegelverval afgehandeld.';
    case 'openbaringStart': {
      const st = startOpenbaring();
      await zorgVoorOpenbaring(app.client);
      return `Openbaring gestart op ${st.startDatum}; blad 1 geplaatst (of ingehaald).`;
    }
    case 'openbaringVolgend': {
      // Het volgende blad nu leggen in plaats van morgen: de startdatum een werkdag terugzetten.
      const st = loadOpenbaring();
      if (!st?.startDatum) return 'Er loopt geen openbaring — start hem eerst.';
      const terug = new Date(`${st.startDatum}T00:00:00Z`);
      do { terug.setUTCDate(terug.getUTCDate() - 1); } while ([0, 6].includes(terug.getUTCDay()));
      saveOpenbaring({ ...st, startDatum: terug.toISOString().slice(0, 10) });
      await zorgVoorOpenbaring(app.client);
      return 'Volgend blad van de openbaring geplaatst.';
    }
    case 'wereldbordVerversen':
      await updateWereldbord(app.client, true);
      return 'Wereldbord bijgewerkt.';
    // De weekvijand op verzoek laten spotten — handig om de persona en de avatar te controleren,
    // en om hem te porren als het kanaal te stil is.
    case 'weekvijandSpreekt': {
      const persona = weekvijandPersona();
      if (!persona) return 'Er waart geen weekvijand rond om te laten spreken.';
      const gelukt = await vijandSpreekt(app.client, process.env.SLACK_CHANNEL_ID,
        'Spot ongevraagd met de Kroket Illuminati: hoon hun kroket-verering en daag ze uit je aan te vallen. ' +
        'Maximaal 3 zinnen, volledig in jouw karakter. Geen inleidingszin.', 220);
      return gelukt
        ? `${persona.naam} heeft gesproken.`
        : `${persona.naam} kon niet spreken (zie logs — LLM-keten of Slack-fout).`;
    }
    // Tribunaal: de dagelijkse klok nu laten lopen (por versturen, fase laten verstrijken,
    // een zaak zonder grond afblazen). Doet niets als er niets te doen is.
    // De statusmeldings-ronde nu laten lopen: vergelijkt de staat met de vorige ronde en stuurt
    // per lid één DM met wat er is weggevallen. Handig om te zien of `im:write` werkt.
    case 'statusMeldingen': {
      const uit = await meldStatusWijzigingen(app.client);
      if (!uit) return 'Statusmeldingen staan uit (instelling statusMeldingen).';
      if (uit.eersteRonde) return `Snapshot aangelegd voor ${uit.leden} lid/leden — meldingen beginnen bij de eerstvolgende wijziging.`;
      return uit.verstuurd
        ? `Ronde gelopen: ${uit.verstuurd} melding(en) verstuurd.`
        : 'Ronde gelopen: niets veranderd, dus niets verstuurd.';
    }
    // Activiteitsklok opnieuw reconstrueren uit Slack-historie. Handig als je wilt zien wie er
    // echt stil is i.p.v. wat de klok denkt, en als vangnet als de eenmalige backfill faalde.
    case 'activiteitBackfill': {
      const uit = await backfillActiviteitUitSlack(app.client);
      if (!uit) return 'Backfill mislukt — kanaalhistorie niet op te halen (zie logs).';
      return `Klok herbouwd uit ${uit.doorzocht} berichten (${uit.dagen} dagen terug):\n` + uit.regels.join('\n');
    }
    // ── De Grote Amnestie: alle straffen kwijt + het nieuwe stemsysteem aankondigen ────
    // Eenmalige actie bij de overgang. Naast de verbanningen worden ook de gele kaarten en de
    // vergrijpen gewist: laat je die staan, dan springt de eerste voordracht onder het nieuwe
    // systeem meteen naar een verbanning, en dan is de schone lei geen schone lei.
    case 'groteAmnestie': {
      const bans = loadVerbanning();
      const nu = Date.now();
      const bevrijd = Object.entries(bans)
        .filter(([, v]) => nu < new Date(v.tot).getTime())
        .map(([id]) => loadMembers()[id]?.bijnaam || id);
      const kaarten = loadGeleKaarten();
      const metKaart = Object.keys(kaarten).filter(id => (kaarten[id]?.kaarten || []).length).length;
      saveVerbanning({});
      saveGeleKaarten({});
      saveVergrijpen({});
      logGebeurtenis('genade', null, `Grote Amnestie: ${bevrijd.length} verbanning(en) opgeheven, ${metKaart} gele kaart-dossier(s) gewist`);
      const namenZin = bevrijd.length
        ? `De volgende ballingen worden vrijgelaten: ${bevrijd.join(', ')}.`
        : 'Er zaten geen ballingen vast, maar alle dossiers zijn desondanks gewist.';
      const tekst = await kroketResponseMetVangnet(
        `Kondig DE GROTE AMNESTIE af, een eenmalig keerpunt in het Gepaneerde Rijk. Twee dingen tegelijk:\n` +
        `(1) ALLE verbanningen worden opgeheven en alle gele kaarten en vergrijpen zijn gewist — iedereen begint met een schone lei. ${namenZin}\n` +
        `(2) Vanaf nu deelt niemand meer alleen een gele kaart uit. Wie een kaart waardig acht, doet een ANONIEME voordracht; ` +
        `de Raad stemt daarna vijf minuten met emoji's (geel = terecht, groen = onterecht). U stemt zelf mee, uw stem weegt DUBBEL, ` +
        `en u maakt uw keuze meteen bij de voordracht kenbaar. Bij gelijkspel volgt geen kaart: bij twijfel geen straf.\n` +
        `Leg uit waarom u dit doet: recht spreken is te zwaar voor één volgeling alleen, en te belangrijk om in het verborgene te laten. ` +
        `Plechtig, groots, met de toon van een godheid die zijn rijk hervormt. 6-8 zinnen. Geen inleidingszin.`,
        700, false,
        `⚜️ *DE GROTE AMNESTIE* ⚜️\n\n` +
        `> Alle verbanningen zijn opgeheven. Alle gele kaarten en vergrijpen zijn gewist. Iedereen begint met een schone lei.\n` +
        `> ${namenZin}\n\n` +
        `*EN EEN NIEUWE ORDE*\n` +
        `> Niemand deelt nog alleen een gele kaart uit. Wie er een waardig acht, doet een *anonieme voordracht* met \`/kroketgod gelekaart [naam] [reden]\`.\n` +
        `> De Raad stemt daarna *vijf minuten* met emoji: 🟨 terecht · 🟩 onterecht.\n` +
        `> De Kroket God stemt zelf mee, maakt zijn keuze meteen kenbaar, en zijn stem *weegt dubbel*.\n` +
        `> Bij gelijkspel volgt geen kaart — bij twijfel geen straf.\n` +
        `> Leidt een tweede kaart tot een verbanning, dan staat op het bord wie er door het heilige verbond mee valt.\n\n` +
        `— De Almachtige Kroket God`,
        'slim', { lang: true }
      );
      await postMetStem(app.client, process.env.SLACK_CHANNEL_ID, tekst);
      await updateWereldbord(app.client, true);
      return `Amnestie afgekondigd: ${bevrijd.length} verbanning(en) opgeheven, ${metKaart} kaart-dossier(s) gewist.`;
    }
    // Een lopende gele-kaart-stemming nu sluiten, zonder de vijf minuten af te wachten.
    case 'gelekaartSluiten': {
      const poll = loadGeleKaartPoll();
      if (!poll?.actief) return 'Er loopt geen gele-kaart-stemming.';
      const na = await sluitGeleKaartPoll(app.client);
      const naam = loadMembers()[na?.doelwitId]?.bijnaam || 'het lid';
      return `Stemming over ${naam} gesloten: ${na?.uitkomst} (${na?.uitslag?.terecht}-${na?.uitslag?.onterecht}, Kroket God stemde ${na?.uitslag?.god}).`;
    }
    case 'tribunaalKlok': {
      await verwerkTribunaalKlok(app.client);
      const t = readJSON('tribunaal.json', null);
      if (!t || t.fase === 'afgerond') {
        const stilste = Object.entries(loadMembers())
          .map(([id, l]) => ({ naam: l.bijnaam, stil: dagenStil(id), afwezig: isAfwezig(id) }))
          .sort((a, b) => b.stil - a.stil)[0];
        return `Klok gelopen; geen lopende zaak. Langst stil: ${stilste?.naam} (${stilste?.stil} dagen${stilste?.afwezig ? ', afwezig gemeld' : ''}).`;
      }
      return `Klok gelopen; zaak tegen ${loadMembers()[t.doelwitId]?.bijnaam} staat in fase "${t.fase}".`;
    }
    // Ongedaan maken van het laatste vonnis — de omkeerbaarheid die het tribunaal draagbaar maakt.
    case 'archiefHerstelLaatste': {
      const archief = loadArchief();
      const laatste = Object.entries(archief).sort((a, b) => (b[1].gearchiveerd || 0) - (a[1].gearchiveerd || 0))[0];
      if (!laatste) return 'Het archief is leeg — er is niemand om te herstellen.';
      const rec = herstelLid(laatste[0]);
      if (!rec) return 'Herstellen mislukt (zie logs).';
      await postToChannel(app.client, process.env.SLACK_CHANNEL_ID,
        `🕊️ *DE POORT HEROPENT* 🕊️\n\n> *${rec.lid.bijnaam}* is hersteld in de Kroket Illuminati. Roem, relikwieën en verleden zijn onaangetast.\n\n— De Hoge Frituurraad`);
      return `${rec.lid.bijnaam} hersteld uit het archief.`;
    }
    // Het onderwerp wordt normaal alleen bij een fasewissel gezet (Slack post bij élke wijziging
    // een systeemregel). Deze knop forceert het, bv. direct nadat de scope is toegevoegd.
    case 'wereldOnderwerp': {
      const voor = loadWereld().onderwerp || null;
      await zetKanaalOnderwerp(app.client);
      const na = loadWereld().onderwerp || null;
      if (na && na !== voor) return `Kanaalonderwerp gezet: ${na}`;
      if (na && na === voor) return 'Onderwerp was al actueel — niets gewijzigd.';
      return 'Onderwerp niet gezet (zie logs; ontbreekt de scope groups:write/channels:manage?).';
    }
    // Vult de App Home van álle leden nu. Normaal doet `app_home_opened` dat zelf zodra iemand
    // de tab opent; deze knop is het vangnet als die event-subscriptie (nog) niet aanstaat,
    // en handig direct na een deploy zodat niemand een verouderde view ziet.
    case 'appHomeVerversen': {
      const leden = Object.keys(loadMembers());
      let gelukt = 0, mislukt = 0;
      for (const id of leden) {
        try { await publiceerAppHome(app.client, id); gelukt++; } catch (_) { mislukt++; }
      }
      return `App Home bijgewerkt voor ${gelukt} lid/leden${mislukt ? ` (${mislukt} mislukt)` : ''}.`;
    }
    default:
      throw new Error('Onbekende actie');
  }
}


// ── De Vetpot opent (eenmalig) ────────────────────────────────────────────────
// Eén verkondiging bij de eerste uitrol, gelijk met de ruimere daglimiet. `geopend` wordt vóór het
// posten gezet, zodat een herstart tijdens het posten geen tweede verkondiging oplevert. Hangt
// aan de luide inhaalslagen, dus nooit 's nachts.
async function openVetpotAlsNodig(client) {
  const v = loadVetpot();
  if (v.geopend) return;
  saveVetpot({ ...v, geopend: true });
  await postToChannel(client, process.env.SLACK_CHANNEL_ID,
    `🍯 *DE VETPOT IS GEOPEND* 🍯\n\n` +
    `> De Hoge Frituurraad zet een pot op het vuur en legt er zelf de eerste *${v.pot}* kroketpunten in.\n` +
    `> Van elk offer dat het Vetbad verzwelgt, druipt voortaan een deel in de pot. Hij blijft staan — ook over de zondag heen — tot iemand hem wint.\n` +
    `> Dat is de jackpot, en die is zeldzaam: één op de honderd offers, en *hoogstens één keer per week*. Wie hem raakt, krijgt ×3 én de hele pot (plafond ${VETPOT_MAX}).\n` +
    `> Wie wint, mag de winst meteen nog één keer inzetten: 🎲 *dubbel of niks*.\n` +
    `> En het Vetbad gaat weer ruimer open: *${VETBAD_BASIS_PER_DAG} offers per dag*.\n\n— De Hoge Frituurraad`);
  await updateWereldbord(client, true);
}

// ── Luide inhaalslagen: de weekkampioen en de seizoensfinale ───────────────────
// Beide verkondigingen zijn de grootste momenten van hun cyclus (een week, respectievelijk zes
// weken). Ze stonden zonder tijdpoort in de opstartroutine, en de bot herstart dagelijks om 03:00 —
// dus werden ze 's nachts uitgesproken, in een leeg kanaal, en zag niemand ze. Nu vuren ze pas
// ná 09:00 Amsterdamse tijd, en haalt de cron van 09:00 in wat de opstart oversloeg.
//
// Beide onderdelen zijn idempotent en dragen hun eigen slot: `voerWeekkampioenUit` schrijft de
// weekreset-marker, en `beslechtSeizoen` valt op zijn status-guard. Twee keer aanroepen op één
// ochtend levert dus één verkondiging op.
async function voerLuideInhaalslagen(herkomst) {
  if (!vandaagMomentGeweest(INHAALSLAG_MOMENT.uur, INHAALSLAG_MOMENT.min)) {
    console.log(`🌙 Inhaalslagen uitgesteld (${herkomst}): vóór ${INHAALSLAG_MOMENT.uur}:00 blijft de Kroket God stil.`);
    return;
  }
  // Weekreset: was de bot down tijdens de zondag-23:59-cron, dan is er niet gereset, geen
  // kampioen gekroond en geen profeet gezet.
  try {
    const marker = readJSON('weekreset.json', { week: null });
    if (marker.week !== null && marker.week !== getMondayOfWeek()) {
      console.warn(`⚠️ Weekreset gemist (${herkomst}) — inhaalslag: kampioen + reset alsnog.`);
      await voerWeekkampioenUit(app.client);
    }
  } catch (err) {
    console.error('Fout bij weekreset-inhaalslag:', err);
  }
  // Zakgeld: ná de weekreset hierboven, want die leegt de lijst. Vangt een gemiste 08:00-ronde op
  // (bot plat, of de reset zelf werd pas net ingehaald) en vult aan wie het deze week nog mist.
  try {
    await deelZakgeldUit(app.client);
  } catch (err) {
    console.error('Fout bij zakgeld-inhaalslag:', err);
  }
  try {
    await openVetpotAlsNodig(app.client);
  } catch (err) {
    console.error('Fout bij openen Vetpot:', err);
  }
  // Seizoenscampagne: de fase wordt uit de datum berekend, dus een gemiste maandag-cron wordt
  // hier alsnog aangekondigd — en een seizoen dat tijdens de downtime uit de tijd liep, beslecht.
  try {
    await zorgVoorSeizoen(app.client);
  } catch (err) {
    console.error('Fout bij seizoen-inhaalslag:', err);
  }
}

// Dagelijks 09:00 — het vangnet onder de opstartroutine hierboven. Bewust op een eigen
// expressie (niet op '5 9 * * 1' van de fasewissel): CRON_LABELS en de overslaan-vlag van het
// dashboard werken per expressie, dus twee features op één expressie delen elkaars schakelaar.
planCron('0 9 * * *', async () => {
  await voerLuideInhaalslagen('cron 09:00');
});

