// ── Crashdetectie ──────────────────────────────────────────────────────────────
// Vangt onverwachte uitzonderingen op en herstart via Docker.

let _rejectionTeller = 0;
let _rejectionReset  = Date.now();

process.on('uncaughtException', async (err) => {
  console.error('💥 Uncaught exception:', err);
  // Forceer exit na max 3s, ook als de Slack-post hangt (anders zombie-proces dat Docker niet
  // herstart). unref() zodat deze timer zelf het proces niet kunstmatig in leven houdt.
  setTimeout(() => process.exit(1), 3000).unref();
  try {
    await app.client.chat.postMessage({
      channel: process.env.SLACK_CHANNEL_ID,
      text: '⚜️ _De heilige frituurinstallatie heeft een onverwachte storing ondervonden. De Kroket God hervat zijn dienst zo spoedig mogelijk._\n\n— De Almachtige Kroket God',
    });
  } catch (_) {}
  process.exit(1);
});

process.on('unhandledRejection', (reason) => {
  console.error('💥 Unhandled rejection:', reason);
  // Tel herhaalde rejections — als er >5 zijn binnen 1 minuut is er structureel iets mis
  const nu = Date.now();
  if (nu - _rejectionReset > 60_000) { _rejectionTeller = 0; _rejectionReset = nu; }
  _rejectionTeller++;
  if (_rejectionTeller > 5) {
    console.error('💥 Te veel unhandled rejections — geforceerde herstart via Docker.');
    process.exit(1);
  }
});

// ── Graceful shutdown ──────────────────────────────────────────────────────────
// docker stop/restart stuurt SIGTERM voor kill. Zonder handler worden:
// - lopende JSON-writes afgekapt (datacorruptie)
// - de Slack WebSocket niet netjes gesloten (reconnect-delays)
// - node-cron taken niet gestopt (process hangt)

async function gracefulShutdown(signaal) {
  console.log(`🛑 ${signaal} ontvangen — graceful shutdown...`);
  // Forceer exit na max 5s, ook als app.stop() of een cron-stop blijft hangen.
  setTimeout(() => process.exit(0), 5000).unref();
  isReady = false;
  // Stop alle geplande cron-taken
  for (const taak of geplandeCrons) {
    try { taak.stop(); } catch (_) {}
  }
  // Stop Bolt (sluit WebSocket netjes)
  try { await app.stop(); } catch (_) {}
  console.log('✅ Kroket God netjes afgesloten.');
  process.exit(0);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT',  () => gracefulShutdown('SIGINT'));

// ── Start ──────────────────────────────────────────────────────────────────────

(async () => {
  backfillAchievements();
  backfillRoem();
  // Vóór laadArchief: de migratie herschrijft het archiefbestand, en de index hoort de schone
  // versie in te lezen. Een fout hier mag de opstart nooit tegenhouden.
  try { wisVloekKopersUitArchief(); }
  catch (err) { console.error('⚠️ Vloek-anonimiteit herstellen mislukt:', err.message); }
  // Het Grote Archief in het geheugen indexeren. Bewust bij opstarten en niet lui bij de eerste
  // zoekopdracht: dan zou het eerste bericht van de dag de indexeertijd op zijn bord krijgen.
  laadArchief();
  seedStatHistorie(); // vul de trendgrafieken met de events van deze week (alleen als nog leeg)
  controleerBackupDekking(); // waarschuwt over state die buiten de backup valt
  maakBackup(); // direct backup bij opstarten
  console.log(`🧩 ${FEATURES.length} features geregistreerd; ${backupBestanden().length} bestanden in de backup.`);
  await app.start();
  isReady = true;
  console.log('⚜️ De Kroket God is wakker. Health: http://localhost:3001/health');
  // Eigen bot-user-ID ophalen: nodig om @-mentions van de Kroket God te herkennen in gewone
  // message-events (zodat personas die niet kapen). Faalt dit, dan blijft de check inert.
  try {
    const auth = await app.client.auth.test();
    BOT_USER_ID = auth.user_id;
    onthoudBotScopes(auth); // heeft de bot files:read? Dan biedt het gastvenster een upload aan.
    console.log(`🤖 Bot-user-ID: ${BOT_USER_ID}`);
  } catch (err) {
    console.warn('⚠️ Kon bot-user-ID niet ophalen:', err.message);
  }
  laadPersistenteTestKanalen(); // eerder geleerde test-ID's van disk (overleeft herstart)
  // Na een deploy of herstart iedereen meteen de nieuwe Home geven, niet pas als hij de tab
  // opent. Even wachten zodat de opstartdrukte (crons, wereldbord) eerst voorbij is; de
  // slackLimiter spreidt de publishes daarna vanzelf.
  setTimeout(() => {
    const leden = Object.keys(loadMembers());
    console.log(`🏠 App Home verversen voor ${leden.length} leden na opstart`);
    for (const id of leden) publiceerAppHome(app.client, id).catch(() => {});
  }, 15_000);
  if (TEST_KANAAL_IDS.size > 0) console.log(`🧪 Testkanaal-ID's bekend: ${[...TEST_KANAAL_IDS].join(', ')}`);
  await laadTestKanaalIds(app.client); // aanvulling via API (kan op missing_scope falen — niet erg)
  await laadNederlandseFeestdagen(); // feestdagen voor Nager.at integratie
  // Inhaalslag weekreset: was de bot down tijdens de zondag-23:59-cron, dan is er niet gereset,
  // geen kampioen gekroond en geen profeet gezet. Dankzij de nachtelijke herstart (03:00)
  // draait deze check elke ochtend. Eerste run ooit: marker initialiseren zonder reset.
  // Eerste run ooit: alleen de marker initialiseren, zonder reset en zonder kroning.
  try {
    const marker = readJSON('weekreset.json', { week: null });
    if (marker.week === null) writeJSON('weekreset.json', { week: getMondayOfWeek() });
  } catch (err) {
    console.error('Fout bij initialiseren weekreset-marker:', err);
  }
  // De luidruchtige inhaalslagen (weekkampioen, seizoensfinale) niet vóór 09:00. Is het nog
  // te vroeg, dan haalt de cron van 09:00 ze diezelfde ochtend alsnog in.
  await voerLuideInhaalslagen('opstart');
  // Het wereldbord plaatsen of bijwerken zodat het gepinde bericht direct na een deploy klopt.
  try {
    await updateWereldbord(app.client, true);
  } catch (err) {
    console.error('Fout bij wereldbord bij opstart:', err);
  }
  // Tribunaal: eerst de activiteitsklok van nieuwe/onbekende leden op NU zetten (anders zou
  // iedereen bij de eerste opstart direct tribunaalwaardig zijn), daarna de klok verwerken —
  // dat is tevens de inhaalslag voor een gemiste dagelijkse cron.
  try {
    zorgVoorActiviteitBasis();
    // Zolang er nog geseede placeholder-klokken staan: die vervangen door de echte laatste
    // activiteit uit Slack. Eenmalig — na de backfill is `geseed` weg en gebeurt dit niet meer.
    if (Object.values(loadActiviteit()).some(a => a?.geseed)) {
      await backfillActiviteitUitSlack(app.client);
    }
    await verwerkTribunaalKlok(app.client);
  } catch (err) {
    console.error('Fout bij tribunaal-inhaalslag:', err);
  }
  // Weekvijand: is de maandagse opkomst gemist (bot down), dan alsnog laten oprijzen.
  try {
    await zorgVoorWeekvijand();
  } catch (err) {
    console.error('Fout bij weekvijand-inhaalslag:', err);
  }
  // Ambten: is de maandagse hertelling gemist, dan alsnog. Zelf gepoort op de weekstart én op
  // maandag 09:10, dus dit kan de verkondiging niet naar de nacht trekken.
  try {
    await zorgVoorAmbten(app.client);
  } catch (err) {
    console.error('Fout bij ambten-inhaalslag:', err);
  }
  // Een verbanning kan tijdens de downtime zijn gevallen; dan staat er nu een dode zetel.
  try {
    await zorgVoorAmbtsVacatures(app.client);
  } catch (err) {
    console.error('Fout bij ambtsvacature-inhaalslag:', err);
  }
  // De wekelijkse wrok-toestanden. Beide zijn gepoort op de weekstart, dus dit is de inhaalslag
  // voor een gemiste maandag — en beide zwijgen onder hun drempel.
  if (vandaagMomentGeweest(INHAALSLAG_MOMENT.uur, INHAALSLAG_MOMENT.min) && !isWeekendAms()) {
    try { await zorgVoorVete(app.client); }
    catch (err) { console.error('Fout bij vete-inhaalslag:', err); }
    try { await zorgVoorZwarteKorst(app.client); }
    catch (err) { console.error('Fout bij Zwarte Korst-inhaalslag:', err); }
  }
  // De openbaring: een gemist blad wordt hier alsnog gelegd (en anders door de kwartier-cron).
  try {
    await zorgVoorOpenbaring(app.client);
  } catch (err) {
    console.error('Fout bij openbaring-inhaalslag:', err);
  }
  // Het Grote Archief: bij een leeg archief eenmalig vullen uit de Slack-historie. Staat
  // bewust achteraan de opstart — het is een gratis extraatje, niet iets waar de bot op wacht.
  try {
    await backfillArchiefUitSlack(app.client);
  } catch (err) {
    console.error('Fout bij archief-backfill:', err);
  }
  // Inhaalslag voor het Paarboek: stond de bot maandagochtend uit, dan hoort een wrok niet een
  // week langer te blijven staan. Idempotent op de weeksleutel, dus dit is gratis als de cron
  // gewoon gedraaid heeft.
  schuifPaarboek();
})();
